import type { RawQ } from "../types";
// Naḥw and ṣarf theory with non-Quranic example sentences: parts of speech, iʿrāb, case signs, sentence types, functions, tawābiʿ, jazm and conditionals, roots, verb forms, weak verbs, plurals, classical works and schools. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  { id: "nht-001", s: "nahw", g: 1, d: 1, t: ["parts-of-speech"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-kalām",
    en: ["Into which three parts do the grammarians divide the word (al-kalima)?", ["Noun, verb and particle", "Noun, adjective and verb", "Verb, particle and pronoun", "Subject, predicate and object"], "Every Arabic word is either a noun (ism), a verb (fiʿl) or a particle (ḥarf) that brings a meaning. Adjectives and pronouns are kinds of nouns, and subject or predicate are functions, not parts of speech."],
    de: ["In welche drei Wortarten teilen die Grammatiker das Wort (al-kalima) ein?", ["Nomen, Verb und Partikel", "Nomen, Adjektiv und Verb", "Verb, Partikel und Pronomen", "Subjekt, Prädikat und Objekt"], "Jedes arabische Wort ist entweder ein Nomen (ism), ein Verb (fiʿl) oder eine Partikel (ḥarf), die eine Bedeutung trägt. Adjektive und Pronomen gehören zu den Nomen; Subjekt und Prädikat sind Satzfunktionen, keine Wortarten."],
    ar: ["إلى كم قسمٍ يقسم النحاة الكلمة؟", ["اسم وفعل وحرف", "اسم وصفة وفعل", "فعل وحرف وضمير", "مبتدأ وخبر ومفعول"], "الكلمة اسم أو فعل أو حرف جاء لمعنى، والصفة والضمير من أنواع الاسم، وأما المبتدأ والخبر والمفعول فوظائف إعرابية لا أقسام للكلمة."] },

  { id: "nht-002", s: "nahw", g: 1, d: 1, t: ["signs-of-noun", "parts-of-speech"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-kalām",
    en: ["Which of these is a sign that a word is a noun (ism)?", ["It can take the definite article al-", "It can be preceded by the particle qad", "It can be preceded by the particle sawfa", "It can take a silent feminine tāʾ"], "Nouns are recognised by jarr, tanwīn, the article al- and the prepositions. Qad, sīn, sawfa and the silent feminine tāʾ (as in qāmat) are signs of the verb."],
    de: ["Welches ist ein Kennzeichen dafür, dass ein Wort ein Nomen (ism) ist?", ["Es kann den Artikel al- annehmen", "Es kann nach der Partikel qad stehen", "Es kann nach der Partikel saufa stehen", "Es kann ein ruhendes weibliches tāʾ annehmen"], "Nomen erkennt man am Genitiv, am Tanwīn, am Artikel al- und an den Präpositionen. Qad, sa-, saufa und das ruhende weibliche tāʾ (wie in qāmat) sind Kennzeichen des Verbs."],
    ar: ["أيّ هذه علامة على أن الكلمة اسم؟", ["قبول «أل» التعريف", "دخول «قد» عليها", "دخول «سوف» عليها", "قبول تاء التأنيث الساكنة"], "يُعرف الاسم بالخفض والتنوين ودخول الألف واللام وحروف الخفض، أما قد والسين وسوف وتاء التأنيث الساكنة فعلامات الفعل."] },

  { id: "nht-003", s: "nahw", g: 1, d: 1, t: ["signs-of-verb", "parts-of-speech"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-kalām",
    en: ["Which phrase begins with a particle that marks the following word as a verb?", ["قَدْ نَجَحَ", "فِي البَيْتِ", "إِلَى المَدْرَسَةِ", "مِنَ السُّوقِ"], "Qad enters only on verbs, so it is one of the signs of the verb. Fī, ilā and min are prepositions, which enter only on nouns."],
    de: ["Welche Wendung beginnt mit einer Partikel, die das folgende Wort als Verb kennzeichnet?", ["قَدْ نَجَحَ", "فِي البَيْتِ", "إِلَى المَدْرَسَةِ", "مِنَ السُّوقِ"], "Qad tritt nur vor Verben und ist daher ein Kennzeichen des Verbs. Fī, ilā und min sind Präpositionen, die nur vor Nomen stehen."],
    ar: ["أيّ العبارات تبدأ بحرف يدل على أن ما بعده فعل؟", ["قَدْ نَجَحَ", "فِي البَيْتِ", "إِلَى المَدْرَسَةِ", "مِنَ السُّوقِ"], "«قد» لا تدخل إلا على الفعل فهي من علاماته، أما «في» و«إلى» و«من» فحروف جر لا تدخل إلا على الأسماء."] },

  { id: "nht-004", s: "nahw", g: 1, d: 1, t: ["case-signs"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb ʿalāmāt al-iʿrāb",
    en: ["What is the original sign of rafʿ (the nominative case)?", ["Ḍamma", "Fatḥa", "Kasra", "Sukūn"], "The original signs are ḍamma for rafʿ, fatḥa for naṣb, kasra for jarr and sukūn for jazm. Other signs (letters, deletion) are substitutes."],
    de: ["Was ist das ursprüngliche Zeichen des rafʿ (Nominativ)?", ["Ḍamma", "Fatḥa", "Kasra", "Sukūn"], "Die ursprünglichen Zeichen sind Ḍamma für rafʿ, Fatḥa für naṣb, Kasra für ǧarr und Sukūn für ǧazm. Andere Zeichen (Buchstaben, Wegfall) sind Ersatzzeichen."],
    ar: ["ما العلامة الأصلية للرفع؟", ["الضمة", "الفتحة", "الكسرة", "السكون"], "العلامات الأصلية: الضمة للرفع، والفتحة للنصب، والكسرة للجر، والسكون للجزم، وما سواها علامات فرعية نائبة."] },

  { id: "nht-005", s: "nahw", g: 1, d: 1, t: ["case-signs", "jazm"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb ʿalāmāt al-iʿrāb",
    en: ["What is the original sign of jazm (the jussive mood)?", ["Sukūn", "Ḍamma", "Fatḥa", "Kasra"], "Jazm is found only in the present-tense verb, and its original sign is sukūn, as in lam yaktub. Its substitute sign is deletion of a letter."],
    de: ["Was ist das ursprüngliche Zeichen des ǧazm (Apokopat)?", ["Sukūn", "Ḍamma", "Fatḥa", "Kasra"], "Den ǧazm gibt es nur beim Präsensverb; sein ursprüngliches Zeichen ist das Sukūn, wie in lam yaktub. Sein Ersatzzeichen ist der Wegfall eines Buchstabens."],
    ar: ["ما العلامة الأصلية للجزم؟", ["السكون", "الضمة", "الفتحة", "الكسرة"], "الجزم خاص بالفعل المضارع، وعلامته الأصلية السكون نحو: لم يكتبْ، وينوب عنه الحذف."] },

  { id: "nht-006", s: "nahw", g: 1, d: 1, t: ["case-signs", "prepositions"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb makhfūḍāt al-asmāʾ",
    en: ["In the sentence ذَهَبَ الوَلَدُ إِلَى المَسْجِدِ, what is the case of المَسْجِدِ?", ["Majrūr (genitive)", "Marfūʿ (nominative)", "Manṣūb (accusative)", "Majzūm (jussive)"], "The noun comes after the preposition ilā, and a noun after a preposition is majrūr, here with a kasra. Jazm never occurs in nouns."],
    de: ["Welchen Fall hat المَسْجِدِ im Satz ذَهَبَ الوَلَدُ إِلَى المَسْجِدِ?", ["Maǧrūr (Genitiv)", "Marfūʿ (Nominativ)", "Manṣūb (Akkusativ)", "Maǧzūm (Apokopat)"], "Das Nomen steht nach der Präposition ilā, und ein Nomen nach einer Präposition ist maǧrūr, hier mit Kasra. Den ǧazm gibt es bei Nomen nie."],
    ar: ["ما حكم كلمة «المسجدِ» في جملة: ذهبَ الولدُ إلى المسجدِ؟", ["مجرورة", "مرفوعة", "منصوبة", "مجزومة"], "جاءت بعد حرف الجر «إلى» فهي اسم مجرور وعلامة جره الكسرة، والجزم لا يدخل الأسماء."] },

  { id: "nht-007", s: "nahw", g: 1, d: 1, t: ["nominal-sentence"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-mubtadaʾ wa-l-khabar",
    en: ["In the sentence الطَّالِبُ مُجْتَهِدٌ, what is الطَّالِبُ?", ["Mubtadaʾ (topic)", "Khabar (predicate)", "Fāʿil (doer)", "Mafʿūl bihi (object)"], "A nominal sentence opens with a noun, the mubtadaʾ, which is marfūʿ and free of any governing word; مُجْتَهِدٌ is its khabar. There is no verb, so there can be no fāʿil."],
    de: ["Was ist الطَّالِبُ im Satz الطَّالِبُ مُجْتَهِدٌ?", ["Mubtadaʾ (Thema)", "Ḫabar (Prädikat)", "Fāʿil (Handelnder)", "Mafʿūl bihi (Objekt)"], "Ein Nominalsatz beginnt mit einem Nomen, dem Mubtadaʾ, das marfūʿ ist und von keinem Regens abhängt; مُجْتَهِدٌ ist sein Ḫabar. Ohne Verb gibt es keinen Fāʿil."],
    ar: ["ما إعراب «الطالبُ» في جملة: الطالبُ مجتهدٌ؟", ["مبتدأ مرفوع", "خبر مرفوع", "فاعل مرفوع", "مفعول به منصوب"], "الجملة اسمية بدأت باسم مرفوع عارٍ عن العوامل اللفظية وهو المبتدأ، و«مجتهدٌ» خبره، ولا فاعل لعدم وجود الفعل."] },

  { id: "nht-008", s: "nahw", g: 1, d: 1, t: ["nominal-sentence"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-mubtadaʾ wa-l-khabar",
    en: ["In the sentence الجَوُّ جَمِيلٌ, what function does جَمِيلٌ have?", ["Khabar (predicate)", "Mubtadaʾ (topic)", "Naʿt (adjective)", "Ḥāl (circumstance)"], "جَمِيلٌ completes the meaning of the mubtadaʾ and is marfūʿ, so it is the khabar. It cannot be a naʿt here: an attribute of a definite noun would itself be definite (al-jamīl)."],
    de: ["Welche Funktion hat جَمِيلٌ im Satz الجَوُّ جَمِيلٌ?", ["Ḫabar (Prädikat)", "Mubtadaʾ (Thema)", "Naʿt (Attribut)", "Ḥāl (Zustand)"], "جَمِيلٌ vervollständigt die Aussage über das Mubtadaʾ und ist marfūʿ, also Ḫabar. Ein Attribut zu einem bestimmten Nomen müsste selbst bestimmt sein (al-ǧamīl)."],
    ar: ["ما وظيفة «جميلٌ» في جملة: الجوُّ جميلٌ؟", ["خبر", "مبتدأ", "نعت", "حال"], "«جميلٌ» تتم به الفائدة مع المبتدأ وهو مرفوع فهو خبر، ولا يصح أن يكون نعتًا لأن نعت المعرفة يكون معرفة (الجميل)."] },

  { id: "nht-009", s: "nahw", g: 1, d: 1, t: ["verbal-sentence", "fail"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-fāʿil",
    en: ["In the sentence كَتَبَ الطَّالِبُ الدَّرْسَ, what is the iʿrāb of الطَّالِبُ?", ["Fāʿil, marfūʿ", "Mubtadaʾ, marfūʿ", "Mafʿūl bihi, manṣūb", "Khabar, marfūʿ"], "The student is the one who performed the action of the verb kataba, so he is the fāʿil, which is always marfūʿ. الدَّرْسَ is the object."],
    de: ["Wie lautet der Iʿrāb von الطَّالِبُ im Satz كَتَبَ الطَّالِبُ الدَّرْسَ?", ["Fāʿil, marfūʿ", "Mubtadaʾ, marfūʿ", "Mafʿūl bihi, manṣūb", "Ḫabar, marfūʿ"], "Der Student führt die Handlung des Verbs kataba aus und ist daher Fāʿil, der immer marfūʿ ist. الدَّرْسَ ist das Objekt."],
    ar: ["ما إعراب «الطالبُ» في جملة: كتبَ الطالبُ الدرسَ؟", ["فاعل مرفوع", "مبتدأ مرفوع", "مفعول به منصوب", "خبر مرفوع"], "الطالب هو الذي قام بالكتابة فهو فاعل، والفاعل مرفوع دائمًا، و«الدرسَ» مفعول به."] },

  { id: "nht-010", s: "nahw", g: 1, d: 1, t: ["verbal-sentence", "mafulat"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-mafʿūl bihi",
    en: ["In the sentence كَتَبَ الطَّالِبُ الدَّرْسَ, what is the iʿrāb of الدَّرْسَ?", ["Mafʿūl bihi, manṣūb", "Fāʿil, marfūʿ", "Ḥāl, manṣūb", "Tamyīz, manṣūb"], "The lesson is what the action fell upon, so it is the direct object (mafʿūl bihi), manṣūb with a fatḥa."],
    de: ["Wie lautet der Iʿrāb von الدَّرْسَ im Satz كَتَبَ الطَّالِبُ الدَّرْسَ?", ["Mafʿūl bihi, manṣūb", "Fāʿil, marfūʿ", "Ḥāl, manṣūb", "Tamyīz, manṣūb"], "Die Lektion ist das, worauf die Handlung fällt; sie ist daher direktes Objekt (mafʿūl bihi), manṣūb mit Fatḥa."],
    ar: ["ما إعراب «الدرسَ» في جملة: كتبَ الطالبُ الدرسَ؟", ["مفعول به منصوب", "فاعل مرفوع", "حال منصوبة", "تمييز منصوب"], "الدرس هو ما وقع عليه فعل الفاعل فهو مفعول به منصوب وعلامة نصبه الفتحة."] },

  { id: "nht-011", s: "nahw", g: 1, d: 2, t: ["verbal-sentence", "nominal-sentence"], src: "Ibn Hishām, Mughnī al-Labīb, on the divisions of the sentence",
    en: ["Which of these is a verbal sentence (jumla fiʿliyya)?", ["يَقْرَأُ الوَلَدُ الكِتَابَ", "البَيْتُ كَبِيرٌ", "هَذَا كِتَابٌ جَدِيدٌ", "فِي الدَّارِ رَجُلٌ"], "A verbal sentence is one that begins with a verb, here yaqraʾu. The other three contain no verb at all and are nominal sentences (the last with a fronted khabar)."],
    de: ["Welcher dieser Sätze ist ein Verbalsatz (ǧumla fiʿliyya)?", ["يَقْرَأُ الوَلَدُ الكِتَابَ", "البَيْتُ كَبِيرٌ", "هَذَا كِتَابٌ جَدِيدٌ", "فِي الدَّارِ رَجُلٌ"], "Ein Verbalsatz beginnt mit einem Verb, hier yaqraʾu. Die anderen drei enthalten kein Verb und sind Nominalsätze (der letzte mit vorangestelltem Ḫabar)."],
    ar: ["أيّ هذه الجمل جملة فعلية؟", ["يَقْرَأُ الوَلَدُ الكِتَابَ", "البَيْتُ كَبِيرٌ", "هَذَا كِتَابٌ جَدِيدٌ", "فِي الدَّارِ رَجُلٌ"], "الجملة الفعلية ما صُدِّرت بفعل، وهي هنا «يقرأ»، وأما البواقي فجمل اسمية لا فعل فيها، والأخيرة خبرها مقدَّم."] },

  { id: "nht-012", s: "nahw", g: 1, d: 2, t: ["mabni-murab"], src: "Ibn Hishām, Sharḥ Qaṭr al-Nadā, on the built and the declined",
    en: ["Which kind of verb is always mabnī (fixed in its ending)?", ["The past-tense verb (māḍī)", "The present-tense verb (muḍāriʿ)", "The present verb after lam", "The present verb after lan"], "The past-tense verb is always mabnī. The present-tense verb is muʿrab: it changes for rafʿ, naṣb and jazm (lan yaktuba, lam yaktub), unless a nūn of emphasis or of the feminine plural is attached."],
    de: ["Welche Verbform ist immer mabnī (unveränderlich in der Endung)?", ["Das Perfekt (māḍī)", "Das Präsens (muḍāriʿ)", "Das Präsens nach lam", "Das Präsens nach lan"], "Das Perfekt ist immer mabnī. Das Präsens ist muʿrab und verändert sich für rafʿ, naṣb und ǧazm (lan yaktuba, lam yaktub), außer wenn ein Nūn der Bekräftigung oder des femininen Plurals antritt."],
    ar: ["أيّ الأفعال مبنيّ دائمًا؟", ["الفعل الماضي", "الفعل المضارع", "المضارع بعد «لم»", "المضارع بعد «لن»"], "الماضي مبني دائمًا، وأما المضارع فمعرب يُرفع ويُنصب ويُجزم (لن يكتبَ، لم يكتبْ) ما لم تتصل به نون التوكيد أو نون النسوة."] },

  { id: "nht-013", s: "nahw", g: 1, d: 2, t: ["classical-works"], src: "Ibn Ājurrūm, al-Muqaddima al-Ājurrūmiyya",
    en: ["Who wrote the short primer of grammar known as al-Ājurrūmiyya?", ["Ibn Ājurrūm al-Ṣanhājī", "Ibn Mālik al-Andalusī", "Ibn Hishām al-Anṣārī", "Sībawayh of Baṣra"], "Al-Ājurrūmiyya is named after its author, Abū ʿAbd Allāh Muḥammad ibn Muḥammad ibn Ājurrūm al-Ṣanhājī of Fez. It is traditionally the first grammar text memorised by beginners."],
    de: ["Wer verfasste die kurze Grammatik-Einführung al-Āǧurrūmiyya?", ["Ibn Āǧurrūm aṣ-Ṣanhāǧī", "Ibn Mālik al-Andalusī", "Ibn Hišām al-Anṣārī", "Sībawaih aus Basra"], "Die Āǧurrūmiyya ist nach ihrem Verfasser benannt, Abū ʿAbdallāh Muḥammad ibn Muḥammad ibn Āǧurrūm aṣ-Ṣanhāǧī aus Fes. Sie ist traditionell der erste Grammatiktext, den Anfänger auswendig lernen."],
    ar: ["مَن صاحب المتن النحوي المختصر المعروف بالآجرومية؟", ["ابن آجروم الصنهاجي", "ابن مالك الأندلسي", "ابن هشام الأنصاري", "سيبويه البصري"], "الآجرومية منسوبة إلى مؤلفها أبي عبد الله محمد بن محمد بن آجروم الصنهاجي الفاسي، وهي أول ما يحفظه المبتدئون في النحو عادة."] },

  { id: "nht-014", s: "nahw", g: 1, d: 2, t: ["substitute-signs", "dual-plural"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb ʿalāmāt al-iʿrāb",
    en: ["In the sentence جَاءَ الطَّالِبَانِ, which sign shows that الطَّالِبَانِ is marfūʿ?", ["The alif", "The ḍamma", "The nūn", "The yāʾ"], "The dual is marfūʿ with an alif in place of the ḍamma, and manṣūb or majrūr with a yāʾ. The nūn is not a case sign: it compensates for the tanwīn of the singular."],
    de: ["Welches Zeichen zeigt im Satz جَاءَ الطَّالِبَانِ, dass الطَّالِبَانِ marfūʿ ist?", ["Das Alif", "Die Ḍamma", "Das Nūn", "Das Yāʾ"], "Der Dual ist marfūʿ mit Alif anstelle der Ḍamma und manṣūb oder maǧrūr mit Yāʾ. Das Nūn ist kein Kasuszeichen, sondern ersetzt das Tanwīn des Singulars."],
    ar: ["ما علامة رفع «الطالبانِ» في جملة: جاءَ الطالبانِ؟", ["الألف", "الضمة", "النون", "الياء"], "المثنى يُرفع بالألف نيابة عن الضمة، ويُنصب ويُجر بالياء، والنون ليست علامة إعراب بل هي عوض عن التنوين في الاسم المفرد."] },

  { id: "nht-015", s: "nahw", g: 1, d: 2, t: ["sarf-roots"], src: "al-Ḥamlāwī, Shadhā al-ʿArf fī Fann al-Ṣarf, on the root and the mīzān",
    en: ["What is the root of the word مَكْتَبَة (library)?", ["k-t-b", "m-k-t", "t-b-h", "m-k-b"], "The mīm and the final tāʾ marbūṭa are added letters; the three root letters kāf, tāʾ, bāʾ carry the core meaning of writing, as in kataba, kitāb and kātib."],
    de: ["Was ist die Wurzel des Wortes مَكْتَبَة (Bibliothek)?", ["k-t-b", "m-k-t", "t-b-h", "m-k-b"], "Das Mīm und das Tāʾ marbūṭa am Ende sind Zusatzbuchstaben; die drei Wurzelbuchstaben Kāf, Tāʾ, Bāʾ tragen die Grundbedeutung „schreiben“, wie in kataba, kitāb und kātib."],
    ar: ["ما جذر كلمة «مكتبة»؟", ["ك ت ب", "م ك ت", "ت ب ة", "م ك ب"], "الميم والتاء المربوطة زائدتان، والأصول الثلاثة الكاف والتاء والباء تحمل معنى الكتابة كما في كتب وكتاب وكاتب."] },

  { id: "nht-016", s: "nahw", g: 1, d: 2, t: ["mushtaqqat"], src: "al-Ḥamlāwī, Shadhā al-ʿArf fī Fann al-Ṣarf, on the active participle",
    en: ["What is the active participle (ism al-fāʿil) of ذَهَبَ?", ["ذَاهِب", "مَذْهُوب", "ذَهَاب", "مَذْهَب"], "From a form I verb the active participle is built on the pattern fāʿil, so dhahaba gives dhāhib. Dhahāb is the maṣdar and madhhab a noun of place."],
    de: ["Wie lautet das aktive Partizip (ism al-fāʿil) von ذَهَبَ?", ["ذَاهِب", "مَذْهُوب", "ذَهَاب", "مَذْهَب"], "Beim Grundstamm wird das aktive Partizip nach dem Muster fāʿil gebildet: aus ḏahaba wird ḏāhib. Ḏahāb ist der Maṣdar und maḏhab ein Ortsnomen."],
    ar: ["ما اسم الفاعل من «ذَهَبَ»؟", ["ذاهِب", "مذهوب", "ذَهاب", "مَذهَب"], "يُصاغ اسم الفاعل من الثلاثي على وزن «فاعِل» فيكون «ذاهب»، و«ذهاب» مصدر، و«مذهب» اسم مكان."] },

  { id: "nht-017", s: "nahw", g: 1, d: 2, t: ["mushtaqqat"], src: "al-Ḥamlāwī, Shadhā al-ʿArf fī Fann al-Ṣarf, on the passive participle",
    en: ["What is the passive participle (ism al-mafʿūl) of كَتَبَ?", ["مَكْتُوب", "كَاتِب", "كِتَابَة", "مَكْتَب"], "From a form I verb the passive participle follows the pattern mafʿūl, so kataba gives maktūb, \"written\". Kātib is the active participle."],
    de: ["Wie lautet das passive Partizip (ism al-mafʿūl) von كَتَبَ?", ["مَكْتُوب", "كَاتِب", "كِتَابَة", "مَكْتَب"], "Beim Grundstamm folgt das passive Partizip dem Muster mafʿūl: aus kataba wird maktūb, „geschrieben“. Kātib ist das aktive Partizip."],
    ar: ["ما اسم المفعول من «كَتَبَ»؟", ["مكتوب", "كاتِب", "كتابة", "مَكتَب"], "يُصاغ اسم المفعول من الثلاثي على وزن «مفعول» فيكون «مكتوب»، أما «كاتب» فاسم فاعل."] },

  { id: "nht-018", s: "nahw", g: 1, d: 2, t: ["prepositions", "parts-of-speech"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb makhfūḍāt al-asmāʾ",
    en: ["Which of these words is a preposition (ḥarf jarr)?", ["عَلَى", "لَمْ", "لَنْ", "إِنَّ"], "ʿAlā puts the following noun in jarr. Lam makes the present verb majzūm, lan makes it manṣūb, and inna governs a nominal sentence."],
    de: ["Welches dieser Wörter ist eine Präposition (ḥarf ǧarr)?", ["عَلَى", "لَمْ", "لَنْ", "إِنَّ"], "ʿAlā setzt das folgende Nomen in den Genitiv. Lam setzt das Präsens in den ǧazm, lan in den naṣb, und inna wirkt auf einen Nominalsatz."],
    ar: ["أيّ هذه الكلمات حرف جر؟", ["على", "لم", "لن", "إنّ"], "«على» تجر الاسم بعدها، و«لم» تجزم المضارع، و«لن» تنصبه، و«إنّ» تدخل على الجملة الاسمية."] },

  { id: "nht-019", s: "nahw", g: 1, d: 2, t: ["kana-sisters", "nominal-sentence"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-ʿawāmil al-dākhila ʿalā al-mubtadaʾ wa-l-khabar",
    en: ["In the sentence كَانَ الجَوُّ بَارِدًا, what is بَارِدًا?", ["Khabar of kāna, manṣūb", "Ism of kāna, marfūʿ", "Ḥāl, manṣūb", "Mafʿūl bihi, manṣūb"], "Kāna enters a nominal sentence, leaves the mubtadaʾ marfūʿ as its ism and makes the khabar manṣūb. So al-jaww is the ism of kāna and bāridan its khabar."],
    de: ["Was ist بَارِدًا im Satz كَانَ الجَوُّ بَارِدًا?", ["Ḫabar von kāna, manṣūb", "Ism von kāna, marfūʿ", "Ḥāl, manṣūb", "Mafʿūl bihi, manṣūb"], "Kāna tritt vor einen Nominalsatz, lässt das Mubtadaʾ als sein Ism im rafʿ und setzt den Ḫabar in den naṣb. Al-ǧaww ist also Ism von kāna, bāridan sein Ḫabar."],
    ar: ["ما إعراب «باردًا» في جملة: كانَ الجوُّ باردًا؟", ["خبر كان منصوب", "اسم كان مرفوع", "حال منصوبة", "مفعول به منصوب"], "كان تدخل على المبتدأ والخبر فترفع المبتدأ ويسمى اسمها، وتنصب الخبر ويسمى خبرها، فـ«الجو» اسمها و«باردًا» خبرها."] },

  { id: "nht-020", s: "nahw", g: 1, d: 2, t: ["classical-works", "grammar-schools"], src: "Ibn al-Anbārī, Nuzhat al-Alibbāʾ fī Ṭabaqāt al-Udabāʾ, biography of Abū al-Aswad",
    en: ["Who is commonly credited with laying the first foundations of Arabic grammar?", ["Abū al-Aswad al-Duʾalī", "Sībawayh", "al-Kisāʾī", "Ibn Mālik"], "Most reports name Abū al-Aswad al-Duʾalī, many of them saying he did so at the prompting of ʿAlī ibn Abī Ṭālib. Sībawayh came later and wrote the first comprehensive book on grammar."],
    de: ["Wem wird allgemein die erste Grundlegung der arabischen Grammatik zugeschrieben?", ["Abū l-Aswad ad-Duʾalī", "Sībawaih", "al-Kisāʾī", "Ibn Mālik"], "Die meisten Berichte nennen Abū l-Aswad ad-Duʾalī, viele davon mit dem Hinweis, er habe dies auf Anregung von ʿAlī ibn Abī Ṭālib getan. Sībawaih kam später und schrieb das erste umfassende Grammatikbuch."],
    ar: ["مَن يُنسب إليه في المشهور وضعُ أول أسس النحو العربي؟", ["أبو الأسود الدؤلي", "سيبويه", "الكسائي", "ابن مالك"], "أكثر الروايات على أن أبا الأسود الدؤلي هو واضع النحو، وفي كثير منها أنه فعل ذلك بإشارة من علي بن أبي طالب، وأما سيبويه فمتأخر عنه وصاحب أول كتاب جامع في النحو."] },

  { id: "nht-021", s: "nahw", g: 2, d: 2, t: ["five-nouns", "substitute-signs"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb ʿalāmāt al-iʿrāb",
    en: ["In the sentence جَاءَ أَبُوكَ, what is the sign of rafʿ in أَبُوكَ?", ["The wāw", "The ḍamma", "The alif", "The kāf"], "Abū is one of the five nouns (ab, akh, ḥam, fū, dhū). When they are muḍāf to something other than the yāʾ of the speaker, they take wāw for rafʿ, alif for naṣb and yāʾ for jarr."],
    de: ["Was ist im Satz جَاءَ أَبُوكَ das Zeichen des rafʿ bei أَبُوكَ?", ["Das Wāw", "Die Ḍamma", "Das Alif", "Das Kāf"], "Abū gehört zu den fünf Nomen (ab, aḫ, ḥam, fū, ḏū). Sind sie an etwas anderes als das Yāʾ des Sprechers annektiert, haben sie Wāw im rafʿ, Alif im naṣb und Yāʾ im ǧarr."],
    ar: ["ما علامة رفع «أبوك» في جملة: جاءَ أبوكَ؟", ["الواو", "الضمة", "الألف", "الكاف"], "«أبو» من الأسماء الخمسة (أب، أخ، حم، فو، ذو)، وهي إذا أضيفت إلى غير ياء المتكلم تُرفع بالواو وتُنصب بالألف وتُجر بالياء."] },

  { id: "nht-022", s: "nahw", g: 2, d: 2, t: ["five-nouns", "substitute-signs"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb ʿalāmāt al-iʿrāb",
    en: ["In the sentence مَرَرْتُ بِأَخِيكَ, what is the sign of jarr in أَخِيكَ?", ["The yāʾ", "The kasra", "The alif", "The wāw"], "Akh is one of the five nouns, which are majrūr with a yāʾ in place of the kasra. Here it follows the preposition bi-."],
    de: ["Was ist im Satz مَرَرْتُ بِأَخِيكَ das Zeichen des ǧarr bei أَخِيكَ?", ["Das Yāʾ", "Die Kasra", "Das Alif", "Das Wāw"], "Aḫ gehört zu den fünf Nomen, die im ǧarr ein Yāʾ anstelle der Kasra haben. Hier steht es nach der Präposition bi-."],
    ar: ["ما علامة جر «أخيك» في جملة: مررتُ بأخيكَ؟", ["الياء", "الكسرة", "الألف", "الواو"], "«أخ» من الأسماء الخمسة، وهي تُجر بالياء نيابة عن الكسرة، وقد جاءت هنا بعد حرف الجر الباء."] },

  { id: "nht-023", s: "nahw", g: 2, d: 2, t: ["dual-plural", "substitute-signs"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb ʿalāmāt al-iʿrāb",
    en: ["In the sentence رَأَيْتُ المُعَلِّمِينَ, what is the sign of naṣb in المُعَلِّمِينَ?", ["The yāʾ", "The fatḥa", "The alif", "The kasra"], "The sound masculine plural is marfūʿ with wāw and manṣūb or majrūr with yāʾ. Its nūn is fatḥa-voweled, unlike the kasra-voweled nūn of the dual."],
    de: ["Was ist im Satz رَأَيْتُ المُعَلِّمِينَ das Zeichen des naṣb bei المُعَلِّمِينَ?", ["Das Yāʾ", "Die Fatḥa", "Das Alif", "Die Kasra"], "Der gesunde maskuline Plural ist marfūʿ mit Wāw und manṣūb oder maǧrūr mit Yāʾ. Sein Nūn trägt Fatḥa, anders als das Nūn des Duals mit Kasra."],
    ar: ["ما علامة نصب «المعلّمين» في جملة: رأيتُ المعلّمينَ؟", ["الياء", "الفتحة", "الألف", "الكسرة"], "جمع المذكر السالم يُرفع بالواو ويُنصب ويُجر بالياء، ونونه مفتوحة بخلاف نون المثنى المكسورة."] },

  { id: "nht-024", s: "nahw", g: 2, d: 2, t: ["dual-plural", "substitute-signs"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb ʿalāmāt al-iʿrāb",
    en: ["In the sentence رَأَيْتُ الطَّالِبَاتِ, what is the sign of naṣb in الطَّالِبَاتِ?", ["A kasra in place of the fatḥa", "A fatḥa as usual", "A yāʾ in place of the fatḥa", "An alif in place of the fatḥa"], "The sound feminine plural is manṣūb with a kasra in place of the fatḥa, so its naṣb and jarr look the same."],
    de: ["Was ist im Satz رَأَيْتُ الطَّالِبَاتِ das Zeichen des naṣb bei الطَّالِبَاتِ?", ["Eine Kasra anstelle der Fatḥa", "Eine Fatḥa wie gewöhnlich", "Ein Yāʾ anstelle der Fatḥa", "Ein Alif anstelle der Fatḥa"], "Der gesunde feminine Plural ist im naṣb mit Kasra anstelle der Fatḥa; naṣb und ǧarr sehen bei ihm daher gleich aus."],
    ar: ["ما علامة نصب «الطالبات» في جملة: رأيتُ الطالباتِ؟", ["الكسرة نيابة عن الفتحة", "الفتحة على الأصل", "الياء نيابة عن الفتحة", "الألف نيابة عن الفتحة"], "جمع المؤنث السالم يُنصب بالكسرة نيابة عن الفتحة، فيستوي نصبه وجره."] },

  { id: "nht-025", s: "nahw", g: 2, d: 3, t: ["mamnu-min-al-sarf", "substitute-signs"], src: "Ibn Hishām, Sharḥ Qaṭr al-Nadā, bāb mā lā yanṣarif",
    en: ["In the sentence مَرَرْتُ بِأَحْمَدَ, why does أَحْمَدَ end in a fatḥa although it is majrūr?", ["It is a diptote: a proper name on a verb pattern", "It is the object of the verb marartu", "It is a ḥāl describing the speaker", "The preposition bi- requires a fatḥa"], "Aḥmad combines being a proper name (ʿalamiyya) with a verb pattern (wazn al-fiʿl), so it is mamnūʿ min al-ṣarf: no tanwīn, and fatḥa in place of kasra in jarr. With al- or as muḍāf it takes a kasra again."],
    de: ["Warum endet أَحْمَدَ im Satz مَرَرْتُ بِأَحْمَدَ auf Fatḥa, obwohl es maǧrūr ist?", ["Es ist diptotisch: ein Eigenname mit Verbmuster", "Es ist das Objekt des Verbs marartu", "Es ist ein Ḥāl, der den Sprecher beschreibt", "Die Präposition bi- verlangt eine Fatḥa"], "Aḥmad vereint Eigennamen (ʿalamiyya) und Verbmuster (wazn al-fiʿl) und ist daher mamnūʿ min aṣ-ṣarf: ohne Tanwīn und im ǧarr mit Fatḥa statt Kasra. Mit al- oder als Muḍāf erhält es wieder die Kasra."],
    ar: ["لماذا جاءت «أحمدَ» مفتوحة وهي مجرورة في جملة: مررتُ بأحمدَ؟", ["لأنها ممنوعة من الصرف للعلمية ووزن الفعل", "لأنها مفعول به للفعل «مررت»", "لأنها حال من المتكلم", "لأن الباء تقتضي الفتح"], "«أحمد» علم على وزن الفعل فهو ممنوع من الصرف، لا ينوَّن ويُجر بالفتحة نيابة عن الكسرة، فإن دخلته «أل» أو أضيف جُرَّ بالكسرة."] },

  { id: "nht-026", s: "nahw", g: 2, d: 3, t: ["five-verbs", "substitute-signs"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb ʿalāmāt al-iʿrāb",
    en: ["In the sentence الطُّلَّابُ يَكْتُبُونَ, what is the sign of rafʿ in يَكْتُبُونَ?", ["The presence of the nūn", "The ḍamma on the bāʾ", "The wāw of the plural", "A ḍamma assumed on the nūn"], "Yaktubūna is one of the five verbs (present verbs ending in alif of the dual, wāw of the plural or yāʾ of the feminine addressee plus nūn). They are marfūʿ by keeping the nūn; the wāw itself is the fāʿil pronoun."],
    de: ["Was ist im Satz الطُّلَّابُ يَكْتُبُونَ das Zeichen des rafʿ bei يَكْتُبُونَ?", ["Das Vorhandensein des Nūn", "Die Ḍamma auf dem Bāʾ", "Das Wāw des Plurals", "Eine angenommene Ḍamma auf dem Nūn"], "Yaktubūna gehört zu den fünf Verben (Präsensformen mit Dual-Alif, Plural-Wāw oder Yāʾ der angesprochenen Frau plus Nūn). Ihr rafʿ zeigt sich am Erhalt des Nūn; das Wāw selbst ist das Fāʿil-Pronomen."],
    ar: ["ما علامة رفع «يكتبون» في جملة: الطلابُ يكتبونَ؟", ["ثبوت النون", "الضمة على الباء", "واو الجماعة", "ضمة مقدرة على النون"], "«يكتبون» من الأفعال الخمسة، وهي تُرفع بثبوت النون، وأما الواو فضمير متصل في محل رفع فاعل."] },

  { id: "nht-027", s: "nahw", g: 2, d: 3, t: ["five-verbs", "jazm"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb ʿalāmāt al-iʿrāb",
    en: ["In the sentence لَمْ يَكْتُبُوا, what is the sign of jazm in يَكْتُبُوا?", ["Deletion of the nūn", "Sukūn on the bāʾ", "Deletion of the wāw", "Sukūn on the wāw"], "The five verbs are manṣūb and majzūm by dropping the nūn. The alif written after the wāw is the so-called separating alif and has no case function."],
    de: ["Was ist im Satz لَمْ يَكْتُبُوا das Zeichen des ǧazm bei يَكْتُبُوا?", ["Der Wegfall des Nūn", "Sukūn auf dem Bāʾ", "Der Wegfall des Wāw", "Sukūn auf dem Wāw"], "Die fünf Verben sind im naṣb und ǧazm am Wegfall des Nūn erkennbar. Das nach dem Wāw geschriebene Alif ist das sogenannte trennende Alif ohne Kasusfunktion."],
    ar: ["ما علامة جزم «يكتبوا» في جملة: لم يكتبوا؟", ["حذف النون", "السكون على الباء", "حذف الواو", "السكون على الواو"], "الأفعال الخمسة تُنصب وتُجزم بحذف النون، والألف بعد الواو هي الألف الفارقة ولا عمل لها في الإعراب."] },

  { id: "nht-028", s: "nahw", g: 2, d: 3, t: ["weak-verbs", "jazm"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb ʿalāmāt al-iʿrāb",
    en: ["In the sentence لَمْ يَدْعُ, what is the sign of jazm in يَدْعُ?", ["Deletion of the final weak letter", "A sukūn on the ʿayn", "Deletion of the nūn", "A ḍamma on the ʿayn"], "Yadʿū ends in a weak letter (wāw). A present verb with a weak final letter is majzūm by deleting that letter; the ḍamma that remains is just a sign of the deleted wāw."],
    de: ["Was ist im Satz لَمْ يَدْعُ das Zeichen des ǧazm bei يَدْعُ?", ["Der Wegfall des schwachen Endbuchstabens", "Sukūn auf dem ʿAin", "Der Wegfall des Nūn", "Eine Ḍamma auf dem ʿAin"], "Yadʿū endet auf einen schwachen Buchstaben (Wāw). Ein Präsens mit schwachem Endbuchstaben wird durch dessen Wegfall maǧzūm; die verbleibende Ḍamma weist nur auf das weggefallene Wāw hin."],
    ar: ["ما علامة جزم «يدعُ» في جملة: لم يدعُ؟", ["حذف حرف العلة", "السكون على العين", "حذف النون", "الضمة على العين"], "«يدعو» معتل الآخر بالواو، والمضارع المعتل الآخر يُجزم بحذف حرف العلة، والضمة الباقية دليل على الواو المحذوفة."] },

  { id: "nht-029", s: "nahw", g: 2, d: 2, t: ["jazm"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb iʿrāb al-afʿāl",
    en: ["Which particle puts the following present-tense verb into jazm?", ["لَمْ", "لَنْ", "أَنْ", "كَيْ"], "Lam negates the past meaning and makes the present verb majzūm (lam yadhhab). Lan, an and kay all make it manṣūb."],
    de: ["Welche Partikel setzt das folgende Präsensverb in den ǧazm?", ["لَمْ", "لَنْ", "أَنْ", "كَيْ"], "Lam verneint mit Vergangenheitsbedeutung und setzt das Präsens in den ǧazm (lam yaḏhab). Lan, an und kai setzen es in den naṣb."],
    ar: ["أيّ الحروف التالية يجزم الفعل المضارع؟", ["لم", "لن", "أن", "كي"], "«لم» حرف نفي وجزم وقلب يجزم المضارع (لم يذهبْ)، وأما «لن» و«أن» و«كي» فتنصبه."] },

  { id: "nht-030", s: "nahw", g: 2, d: 2, t: ["nawasib"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb iʿrāb al-afʿāl",
    en: ["In the sentence لَنْ يَتَأَخَّرَ الطَّالِبُ, why is يَتَأَخَّرَ manṣūb?", ["It comes after the particle lan", "It is a past-tense verb", "It is the object of the sentence", "It comes after a preposition"], "Lan negates the future and makes the present verb manṣūb with a fatḥa. Verbs are never objects or governed by prepositions."],
    de: ["Warum ist يَتَأَخَّرَ im Satz لَنْ يَتَأَخَّرَ الطَّالِبُ manṣūb?", ["Es steht nach der Partikel lan", "Es ist ein Perfekt", "Es ist das Objekt des Satzes", "Es steht nach einer Präposition"], "Lan verneint die Zukunft und setzt das Präsens mit Fatḥa in den naṣb. Verben sind nie Objekt und stehen nie nach Präpositionen."],
    ar: ["لماذا نُصب «يتأخرَ» في جملة: لن يتأخرَ الطالبُ؟", ["لأنه مسبوق بـ«لن»", "لأنه فعل ماضٍ", "لأنه مفعول به", "لأنه مسبوق بحرف جر"], "«لن» حرف نفي ونصب واستقبال ينصب المضارع بالفتحة، والفعل لا يكون مفعولًا ولا يدخل عليه حرف الجر."] },

  { id: "nht-031", s: "nahw", g: 2, d: 2, t: ["kana-sisters"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-ʿawāmil al-dākhila ʿalā al-mubtadaʾ wa-l-khabar",
    en: ["Which of these verbs is one of the sisters of kāna?", ["أَصْبَحَ", "ظَنَّ", "لَعَلَّ", "كَأَنَّ"], "Aṣbaḥa works like kāna: rafʿ for the ism, naṣb for the khabar. Ẓanna belongs to the verbs that take two objects, while laʿalla and kaʾanna are sisters of inna."],
    de: ["Welches dieser Verben gehört zu den Schwestern von kāna?", ["أَصْبَحَ", "ظَنَّ", "لَعَلَّ", "كَأَنَّ"], "Aṣbaḥa wirkt wie kāna: rafʿ für den Ism, naṣb für den Ḫabar. Ẓanna gehört zu den Verben mit zwei Objekten, laʿalla und kaʾanna sind Schwestern von inna."],
    ar: ["أيّ هذه الأفعال من أخوات كان؟", ["أصبح", "ظنّ", "لعلّ", "كأنّ"], "«أصبح» تعمل عمل كان فترفع الاسم وتنصب الخبر، و«ظنّ» تنصب مفعولين، و«لعلّ» و«كأنّ» من أخوات إنّ."] },

  { id: "nht-032", s: "nahw", g: 2, d: 2, t: ["inna-sisters"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-ʿawāmil al-dākhila ʿalā al-mubtadaʾ wa-l-khabar",
    en: ["Which of these words is one of the sisters of inna?", ["لَكِنَّ", "لَيْسَ", "صَارَ", "مَا زَالَ"], "Lākinna, like inna, makes the ism manṣūb and the khabar marfūʿ. Laysa, ṣāra and mā zāla are sisters of kāna, which work the other way round."],
    de: ["Welches dieser Wörter gehört zu den Schwestern von inna?", ["لَكِنَّ", "لَيْسَ", "صَارَ", "مَا زَالَ"], "Lākinna setzt wie inna den Ism in den naṣb und lässt den Ḫabar im rafʿ. Laisa, ṣāra und mā zāla sind Schwestern von kāna und wirken umgekehrt."],
    ar: ["أيّ هذه الكلمات من أخوات إنّ؟", ["لكنّ", "ليس", "صار", "ما زال"], "«لكنّ» تنصب الاسم وترفع الخبر كإنّ، وأما «ليس» و«صار» و«ما زال» فمن أخوات كان وعملها عكس ذلك."] },

  { id: "nht-033", s: "nahw", g: 2, d: 2, t: ["inna-sisters"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-ʿawāmil al-dākhila ʿalā al-mubtadaʾ wa-l-khabar",
    en: ["In the sentence إِنَّ العِلْمَ نُورٌ, what is the iʿrāb of العِلْمَ?", ["Ism of inna, manṣūb", "Khabar of inna, marfūʿ", "Mubtadaʾ, marfūʿ", "Mafʿūl bihi, manṣūb"], "Inna makes the former mubtadaʾ manṣūb as its ism and leaves the khabar marfūʿ, so al-ʿilma is its ism and nūrun its khabar. Inna is a particle, so it has no object."],
    de: ["Wie lautet der Iʿrāb von العِلْمَ im Satz إِنَّ العِلْمَ نُورٌ?", ["Ism von inna, manṣūb", "Ḫabar von inna, marfūʿ", "Mubtadaʾ, marfūʿ", "Mafʿūl bihi, manṣūb"], "Inna setzt das frühere Mubtadaʾ als seinen Ism in den naṣb und lässt den Ḫabar im rafʿ: al-ʿilma ist Ism, nūrun Ḫabar. Inna ist eine Partikel und hat daher kein Objekt."],
    ar: ["ما إعراب «العلمَ» في جملة: إنّ العلمَ نورٌ؟", ["اسم إنّ منصوب", "خبر إنّ مرفوع", "مبتدأ مرفوع", "مفعول به منصوب"], "إنّ تنصب المبتدأ ويسمى اسمها وترفع الخبر ويسمى خبرها، فـ«العلم» اسمها و«نور» خبرها، وهي حرف فلا مفعول لها."] },

  { id: "nht-034", s: "nahw", g: 2, d: 3, t: ["naib-fail", "verbal-sentence"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-mafʿūl alladhī lam yusamma fāʿiluh",
    en: ["In the sentence كُتِبَ الدَّرْسُ, what is the iʿrāb of الدَّرْسُ?", ["Nāʾib fāʿil (deputy agent)", "Fāʿil (agent)", "Mubtadaʾ (topic)", "Mafʿūl bihi (object)"], "Kutiba is passive: the doer is not named and the former object takes its place in rafʿ. The book of al-Ājurrūmiyya calls this \"the object whose agent is not named\"."],
    de: ["Wie lautet der Iʿrāb von الدَّرْسُ im Satz كُتِبَ الدَّرْسُ?", ["Nāʾib al-fāʿil (Stellvertreter)", "Fāʿil (Handelnder)", "Mubtadaʾ (Thema)", "Mafʿūl bihi (Objekt)"], "Kutiba ist Passiv: Der Handelnde wird nicht genannt, und das frühere Objekt tritt an seine Stelle in den rafʿ. Die Āǧurrūmiyya nennt dies „das Objekt, dessen Handelnder nicht genannt ist“."],
    ar: ["ما إعراب «الدرسُ» في جملة: كُتِبَ الدرسُ؟", ["نائب فاعل مرفوع", "فاعل مرفوع", "مبتدأ مرفوع", "مفعول به منصوب"], "«كُتِب» فعل مبني للمجهول، حُذف فاعله وأقيم المفعول مقامه فرُفع، وهو ما يسميه ابن آجروم المفعول الذي لم يُسمَّ فاعله."] },

  { id: "nht-035", s: "nahw", g: 2, d: 2, t: ["hal"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-ḥāl",
    en: ["In the sentence جَاءَ الطَّالِبُ مُسْرِعًا, what is مُسْرِعًا?", ["Ḥāl", "Tamyīz", "Naʿt", "Mafʿūl muṭlaq"], "Musriʿan is an indefinite manṣūb word that describes the state of the student at the time he came, which is the definition of the ḥāl."],
    de: ["Was ist مُسْرِعًا im Satz جَاءَ الطَّالِبُ مُسْرِعًا?", ["Ḥāl", "Tamyīz", "Naʿt", "Mafʿūl muṭlaq"], "Musriʿan ist ein unbestimmtes Wort im naṣb, das den Zustand des Studenten beim Kommen beschreibt – genau das ist der Ḥāl."],
    ar: ["ما إعراب «مسرعًا» في جملة: جاءَ الطالبُ مسرعًا؟", ["حال", "تمييز", "نعت", "مفعول مطلق"], "«مسرعًا» اسم نكرة منصوب يبيّن هيئة الطالب وقت مجيئه، وهذا هو الحال."] },

  { id: "nht-036", s: "nahw", g: 2, d: 3, t: ["tamyiz", "numbers"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-tamyīz",
    en: ["In the sentence اشْتَرَيْتُ عِشْرِينَ كِتَابًا, what is كِتَابًا?", ["Tamyīz", "Ḥāl", "Mafʿūl bihi", "Badal"], "\"Twenty\" is vague until kitāban specifies what is counted, so kitāban is tamyīz of a number, singular and manṣūb. The object of ishtaraytu is ʿishrīna itself."],
    de: ["Was ist كِتَابًا im Satz اشْتَرَيْتُ عِشْرِينَ كِتَابًا?", ["Tamyīz", "Ḥāl", "Mafʿūl bihi", "Badal"], "„Zwanzig“ bleibt unklar, bis kitāban das Gezählte angibt; kitāban ist daher Tamyīz der Zahl, im Singular und naṣb. Das Objekt von ištaraitu ist ʿišrīna selbst."],
    ar: ["ما إعراب «كتابًا» في جملة: اشتريتُ عشرين كتابًا؟", ["تمييز", "حال", "مفعول به", "بدل"], "العدد «عشرين» مبهم فبيّنه «كتابًا» فهو تمييز مفرد منصوب، وأما المفعول به فهو «عشرين» نفسه."] },

  { id: "nht-037", s: "nahw", g: 2, d: 3, t: ["mafulat"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-maṣdar",
    en: ["In the sentence جَلَسْتُ جُلُوسًا هَادِئًا, what is جُلُوسًا?", ["Mafʿūl muṭlaq", "Mafʿūl li-ajlihi", "Mafʿūl fīhi", "Mafʿūl bihi"], "Julūsan is the maṣdar of the same verb jalasa, used manṣūb to describe the kind of sitting; such a maṣdar is the mafʿūl muṭlaq. Jalasa is intransitive, so it has no mafʿūl bihi."],
    de: ["Was ist جُلُوسًا im Satz جَلَسْتُ جُلُوسًا هَادِئًا?", ["Mafʿūl muṭlaq", "Mafʿūl li-aǧlihi", "Mafʿūl fīhi", "Mafʿūl bihi"], "Ǧulūsan ist der Maṣdar desselben Verbs ǧalasa und steht im naṣb, um die Art des Sitzens zu beschreiben; ein solcher Maṣdar ist Mafʿūl muṭlaq. Ǧalasa ist intransitiv und hat kein Mafʿūl bihi."],
    ar: ["ما إعراب «جلوسًا» في جملة: جلستُ جلوسًا هادئًا؟", ["مفعول مطلق", "مفعول لأجله", "مفعول فيه", "مفعول به"], "«جلوسًا» مصدر من لفظ الفعل «جلس» منصوب مبيّن لنوعه فهو مفعول مطلق، والفعل لازم فلا مفعول به له."] },

  { id: "nht-038", s: "nahw", g: 2, d: 3, t: ["mafulat"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb ẓarf al-zamān wa-ẓarf al-makān",
    en: ["In the sentence صُمْتُ يَوْمَ الخَمِيسِ, what is يَوْمَ?", ["Mafʿūl fīhi", "Mafʿūl bihi", "Mafʿūl muṭlaq", "Mafʿūl li-ajlihi"], "Yawma names the time in which the fasting took place and carries the meaning of fī, so it is a ẓarf of time (mafʿūl fīhi), manṣūb and muḍāf to al-khamīsi."],
    de: ["Was ist يَوْمَ im Satz صُمْتُ يَوْمَ الخَمِيسِ?", ["Mafʿūl fīhi", "Mafʿūl bihi", "Mafʿūl muṭlaq", "Mafʿūl li-aǧlihi"], "Yauma nennt die Zeit, in der gefastet wurde, und hat die Bedeutung von fī; es ist daher eine Zeitangabe (Mafʿūl fīhi), manṣūb und an al-ḫamīsi annektiert."],
    ar: ["ما إعراب «يومَ» في جملة: صمتُ يومَ الخميسِ؟", ["مفعول فيه", "مفعول به", "مفعول مطلق", "مفعول لأجله"], "«يوم» اسم زمان وقع فيه الصوم متضمن معنى «في» فهو ظرف زمان منصوب، أي مفعول فيه، وهو مضاف و«الخميس» مضاف إليه."] },

  { id: "nht-039", s: "nahw", g: 2, d: 3, t: ["mafulat"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-mafʿūl min ajlih",
    en: ["In the sentence وَقَفَ الطُّلَّابُ احْتِرَامًا لِلْمُعَلِّمِ, what is احْتِرَامًا?", ["Mafʿūl li-ajlihi", "Mafʿūl muṭlaq", "Ḥāl", "Tamyīz"], "Iḥtirāman is a manṣūb maṣdar that states the reason for standing (out of respect), which defines the mafʿūl li-ajlihi. It is not mafʿūl muṭlaq because it is not from the root of waqafa."],
    de: ["Was ist احْتِرَامًا im Satz وَقَفَ الطُّلَّابُ احْتِرَامًا لِلْمُعَلِّمِ?", ["Mafʿūl li-aǧlihi", "Mafʿūl muṭlaq", "Ḥāl", "Tamyīz"], "Iḥtirāman ist ein Maṣdar im naṣb, der den Grund des Aufstehens angibt (aus Respekt) – das ist der Mafʿūl li-aǧlihi. Mafʿūl muṭlaq ist es nicht, da es nicht von der Wurzel von waqafa stammt."],
    ar: ["ما إعراب «احترامًا» في جملة: وقفَ الطلابُ احترامًا للمعلّمِ؟", ["مفعول لأجله", "مفعول مطلق", "حال", "تمييز"], "«احترامًا» مصدر منصوب يبيّن سبب الوقوف فهو مفعول لأجله، وليس مفعولًا مطلقًا لأنه ليس من لفظ الفعل «وقف»."] },

  { id: "nht-040", s: "nahw", g: 2, d: 3, t: ["naat", "hal"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-naʿt",
    en: ["In the sentence رَأَيْتُ رَجُلًا كَرِيمًا, what is كَرِيمًا?", ["Naʿt (adjective)", "Ḥāl (state)", "Tamyīz (specifier)", "Badal (apposition)"], "Karīman follows the indefinite rajulan in case and indefiniteness and describes it permanently, so it is a naʿt. A ḥāl normally needs a definite owner, which rajulan is not."],
    de: ["Was ist كَرِيمًا im Satz رَأَيْتُ رَجُلًا كَرِيمًا?", ["Naʿt (Attribut)", "Ḥāl (Zustand)", "Tamyīz (Spezifizierung)", "Badal (Apposition)"], "Karīman folgt dem unbestimmten raǧulan in Kasus und Unbestimmtheit und beschreibt ihn als Eigenschaft; es ist daher Naʿt. Ein Ḥāl braucht in der Regel einen bestimmten Bezugsträger, was raǧulan nicht ist."],
    ar: ["ما إعراب «كريمًا» في جملة: رأيتُ رجلًا كريمًا؟", ["نعت", "حال", "تمييز", "بدل"], "«كريمًا» تابع لـ«رجلًا» في الإعراب والتنكير ويصفه فهو نعت، والحال الأصل في صاحبها أن يكون معرفة و«رجلًا» نكرة."] },

  { id: "nht-041", s: "nahw", g: 2, d: 2, t: ["idafa"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb makhfūḍāt al-asmāʾ",
    en: ["In the phrase هَذَا كِتَابُ الطَّالِبِ, what is الطَّالِبِ?", ["Muḍāf ilayh, majrūr", "Naʿt, majrūr", "Badal, majrūr", "Noun after a preposition"], "Kitābu is the muḍāf and al-ṭālibi the muḍāf ilayh, which is always majrūr. There is no preposition in the phrase; the jarr comes from the iḍāfa."],
    de: ["Was ist الطَّالِبِ in der Wendung هَذَا كِتَابُ الطَّالِبِ?", ["Muḍāf ilaih, maǧrūr", "Naʿt, maǧrūr", "Badal, maǧrūr", "Nomen nach einer Präposition"], "Kitābu ist das Muḍāf und aṭ-ṭālibi das Muḍāf ilaih, das stets maǧrūr ist. Eine Präposition gibt es hier nicht; der Genitiv entsteht durch die Iḍāfa."],
    ar: ["ما إعراب «الطالبِ» في: هذا كتابُ الطالبِ؟", ["مضاف إليه مجرور", "نعت مجرور", "بدل مجرور", "اسم مجرور بحرف الجر"], "«كتاب» مضاف و«الطالب» مضاف إليه، والمضاف إليه مجرور دائمًا، ولا حرف جر في العبارة بل الجر بالإضافة."] },

  { id: "nht-042", s: "nahw", g: 2, d: 2, t: ["verb-forms"], src: "al-Ḥamlāwī, Shadhā al-ʿArf fī Fann al-Ṣarf, on the augmented triliteral",
    en: ["To which verb form does عَلَّمَ (to teach) belong?", ["Form II (faʿʿala)", "Form III (fāʿala)", "Form IV (afʿala)", "Form V (tafaʿʿala)"], "ʿAllama doubles the middle radical of ʿalima, the mark of form II, which often makes a verb transitive or causative: \"to make someone know\"."],
    de: ["Zu welchem Verbstamm gehört عَلَّمَ (lehren)?", ["II. Stamm (faʿʿala)", "III. Stamm (fāʿala)", "IV. Stamm (afʿala)", "V. Stamm (tafaʿʿala)"], "ʿAllama verdoppelt den mittleren Radikal von ʿalima, das Kennzeichen des II. Stammes, der oft transitiv oder kausativ macht: „jemanden wissen lassen“."],
    ar: ["على أيّ وزن جاء الفعل «علَّم»؟", ["فعَّل", "فاعَل", "أفعَل", "تفعَّل"], "«علّم» بتضعيف العين من «علِم» على وزن «فعّل»، ومن معانيه التعدية، أي جعل غيره يعلم."] },

  { id: "nht-043", s: "nahw", g: 2, d: 3, t: ["verb-forms"], src: "al-Ḥamlāwī, Shadhā al-ʿArf fī Fann al-Ṣarf, on the meanings of istafʿala",
    en: ["Which meaning does the pattern istafʿala most often carry, as in اسْتَغْفَرَ?", ["Seeking or requesting", "Mutual action", "Taking on a colour", "Repeated intensive action"], "The commonest meaning of form X is ṭalab, seeking: istaghfara is to seek forgiveness. Mutual action belongs to tafāʿala and colours to ifʿalla."],
    de: ["Welche Bedeutung trägt das Muster istafʿala am häufigsten, wie in اسْتَغْفَرَ?", ["Suchen oder Erbitten", "Gegenseitige Handlung", "Annahme einer Farbe", "Wiederholte, intensive Handlung"], "Die häufigste Bedeutung des X. Stammes ist ṭalab, das Erbitten: istaġfara heißt um Vergebung bitten. Gegenseitigkeit gehört zu tafāʿala, Farben zu ifʿalla."],
    ar: ["ما أشهر معاني وزن «استفعل» كما في «استغفر»؟", ["الطلب", "المشاركة", "الدلالة على اللون", "التكثير والمبالغة"], "أشهر معاني «استفعل» الطلب، فـ«استغفر» طلب المغفرة، وأما المشاركة فمن معاني «تفاعل»، والألوان من «افعلّ»."] },

  { id: "nht-044", s: "nahw", g: 2, d: 3, t: ["nida"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-munādā",
    en: ["In the call يَا طَالِبَ العِلْمِ, what is the iʿrāb of طَالِبَ?", ["Munādā muḍāf, manṣūb", "Munādā mabnī on ḍamma", "Mafʿūl bihi, manṣūb", "Ḥāl, manṣūb"], "A vocative noun that is muḍāf is manṣūb, here ṭāliba before al-ʿilmi. Only the single proper name and the intended indefinite are mabnī on ḍamma."],
    de: ["Wie lautet der Iʿrāb von طَالِبَ im Anruf يَا طَالِبَ العِلْمِ?", ["Munādā muḍāf, manṣūb", "Munādā, mabnī auf Ḍamma", "Mafʿūl bihi, manṣūb", "Ḥāl, manṣūb"], "Ein angerufenes Nomen, das Muḍāf ist, steht im naṣb, hier ṭāliba vor al-ʿilmi. Nur der einzelne Eigenname und das gemeinte Unbestimmte sind mabnī auf Ḍamma."],
    ar: ["ما إعراب «طالبَ» في: يا طالبَ العلمِ؟", ["منادى مضاف منصوب", "منادى مبني على الضم", "مفعول به منصوب", "حال منصوبة"], "المنادى المضاف منصوب، و«طالب» مضاف و«العلم» مضاف إليه، وإنما يُبنى على الضم العلمُ المفرد والنكرة المقصودة."] },

  { id: "nht-045", s: "nahw", g: 3, d: 3, t: ["istithna"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-istithnāʾ",
    en: ["In the sentence حَضَرَ الطُّلَّابُ إِلَّا خَالِدًا, why is خَالِدًا manṣūb?", ["It is excepted from a complete affirmative sentence", "It is the direct object of the verb ḥaḍara", "It is a ḥāl coming after illā", "The noun after illā is always manṣūb"], "When the sentence is complete (the excepted-from, al-ṭullāb, is mentioned) and affirmative, the mustathnā after illā must be manṣūb. The last option is a common mistake: in negative or incomplete sentences other cases occur."],
    de: ["Warum ist خَالِدًا im Satz حَضَرَ الطُّلَّابُ إِلَّا خَالِدًا manṣūb?", ["Es ist aus einem vollständigen bejahten Satz ausgenommen", "Es ist das direkte Objekt des Verbs ḥaḍara", "Es ist ein Ḥāl nach illā", "Das Nomen nach illā ist immer manṣūb"], "Ist der Satz vollständig (das Ausgenommene-aus, aṭ-ṭullāb, ist genannt) und bejaht, muss der Mustaṯnā nach illā im naṣb stehen. Die letzte Option ist ein häufiger Fehler: In verneinten oder unvollständigen Sätzen kommen andere Fälle vor."],
    ar: ["لماذا نُصب «خالدًا» في جملة: حضرَ الطلابُ إلا خالدًا؟", ["لأنه مستثنى بإلا من كلام تام موجب", "لأنه مفعول به للفعل «حضر»", "لأنه حال وقعت بعد إلا", "لأن ما بعد إلا منصوب دائمًا"], "إذا كان الكلام تامًا موجبًا وجب نصب المستثنى بإلا، وليس ما بعد إلا منصوبًا دائمًا، ففي المنفي والمفرّغ أحكام أخرى."] },

  { id: "nht-046", s: "nahw", g: 3, d: 4, t: ["istithna", "fail"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-istithnāʾ",
    en: ["In the sentence مَا حَضَرَ إِلَّا خَالِدٌ, what is the iʿrāb of خَالِدٌ?", ["Fāʿil, marfūʿ", "Mustathnā, manṣūb", "Badal, marfūʿ", "Mubtadaʾ, marfūʿ"], "The excepted-from is not mentioned (istithnāʾ mufarragh), so illā has no effect and the noun takes the case its position demands. The verb ḥaḍara needs a fāʿil, so khālidun is the fāʿil."],
    de: ["Wie lautet der Iʿrāb von خَالِدٌ im Satz مَا حَضَرَ إِلَّا خَالِدٌ?", ["Fāʿil, marfūʿ", "Mustaṯnā, manṣūb", "Badal, marfūʿ", "Mubtadaʾ, marfūʿ"], "Das Ausgenommene-aus wird nicht genannt (istiṯnāʾ mufarraġ); illā wirkt daher nicht, und das Nomen erhält den Fall seiner Satzstelle. Das Verb ḥaḍara braucht einen Fāʿil, also ist ḫālidun Fāʿil."],
    ar: ["ما إعراب «خالدٌ» في جملة: ما حضرَ إلا خالدٌ؟", ["فاعل مرفوع", "مستثنى منصوب", "بدل مرفوع", "مبتدأ مرفوع"], "الاستثناء مفرَّغ لعدم ذكر المستثنى منه، فتُلغى «إلا» ويُعرب ما بعدها بحسب موقعه، والفعل «حضر» يطلب فاعلًا فـ«خالد» فاعل."] },

  { id: "nht-047", s: "nahw", g: 3, d: 4, t: ["istithna", "badal"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-istithnāʾ",
    en: ["In the sentence مَا حَضَرَ الطُّلَّابُ إِلَّا خَالِد, which ending(s) may خَالِد take?", ["Naṣb, or rafʿ as a badal of al-ṭullāb", "Naṣb only, as after any illā", "Rafʿ only, as the fāʿil of ḥaḍara", "Jarr only, as a muḍāf ilayh"], "In a complete negative sentence the mustathnā may be manṣūb or follow the excepted-from as a badal; the badal (khālidun) is the preferred option when the exception is of the same kind."],
    de: ["Welche Endung(en) darf خَالِد im Satz مَا حَضَرَ الطُّلَّابُ إِلَّا خَالِد tragen?", ["Naṣb oder rafʿ als Badal von aṭ-ṭullāb", "Nur naṣb, wie nach jedem illā", "Nur rafʿ, als Fāʿil von ḥaḍara", "Nur ǧarr, als Muḍāf ilaih"], "Im vollständigen verneinten Satz darf der Mustaṯnā im naṣb stehen oder dem Ausgenommenen-aus als Badal folgen; der Badal (ḫālidun) ist bei gleichartiger Ausnahme vorzuziehen."],
    ar: ["ما الوجه الجائز في «خالد» في جملة: ما حضرَ الطلابُ إلا خالد؟", ["النصب أو الرفع على البدلية من «الطلاب»", "النصب فقط كما بعد كل «إلا»", "الرفع فقط على الفاعلية", "الجر فقط على الإضافة"], "إذا كان الكلام تامًا منفيًا جاز في المستثنى النصب والإتباع على البدلية، والبدل أرجح في الاستثناء المتصل."] },

  { id: "nht-048", s: "nahw", g: 3, d: 3, t: ["istithna", "idafa"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-istithnāʾ",
    en: ["In the sentence حَضَرَ الطُّلَّابُ غَيْرَ خَالِدٍ, why is خَالِدٍ majrūr?", ["It is the muḍāf ilayh of ghayr", "It comes after a preposition", "Ghayr is a particle of jarr", "It is a badal of al-ṭullāb"], "Ghayr is a noun that carries the case of the exception itself (here manṣūb), and the excepted noun after it is always majrūr as its muḍāf ilayh. The same applies to siwā."],
    de: ["Warum ist خَالِدٍ im Satz حَضَرَ الطُّلَّابُ غَيْرَ خَالِدٍ maǧrūr?", ["Es ist das Muḍāf ilaih von ġair", "Es steht nach einer Präposition", "Ġair ist eine Genitivpartikel", "Es ist ein Badal von aṭ-ṭullāb"], "Ġair ist ein Nomen, das selbst den Fall der Ausnahme trägt (hier naṣb); das ausgenommene Nomen danach ist stets maǧrūr als sein Muḍāf ilaih. Dasselbe gilt für siwā."],
    ar: ["لماذا جُرّ «خالدٍ» في جملة: حضرَ الطلابُ غيرَ خالدٍ؟", ["لأنه مضاف إليه لـ«غير»", "لأنه مسبوق بحرف جر", "لأن «غير» حرف جر", "لأنه بدل من «الطلاب»"], "«غير» اسم يأخذ هو حكم المستثنى بإلا (وهو هنا النصب)، والاسم بعده مجرور دائمًا بالإضافة، ومثلها «سوى»."] },

  { id: "nht-049", s: "nahw", g: 3, d: 4, t: ["mafulat"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-mafʿūl maʿah",
    en: ["In the classic grammar example سِرْتُ وَالنِّيلَ, what is النِّيلَ?", ["Mafʿūl maʿahu", "Maʿṭūf on the subject", "Mafʿūl fīhi", "Mafʿūl bihi"], "The wāw here means \"along with\" (wāw al-maʿiyya): I travelled alongside the Nile. Coordination is impossible because the river does not travel, so the noun is manṣūb as mafʿūl maʿahu."],
    de: ["Was ist النِّيلَ im klassischen Grammatikbeispiel سِرْتُ وَالنِّيلَ?", ["Mafʿūl maʿahu", "Auf das Subjekt koordiniert", "Mafʿūl fīhi", "Mafʿūl bihi"], "Das Wāw bedeutet hier „zusammen mit“ (wāw al-maʿiyya): Ich reiste den Nil entlang. Eine Koordination ist unmöglich, da der Fluss nicht reist; das Nomen ist daher als Mafʿūl maʿahu manṣūb."],
    ar: ["ما إعراب «النيلَ» في المثال النحوي المشهور: سرتُ والنيلَ؟", ["مفعول معه", "معطوف على الفاعل", "مفعول فيه", "مفعول به"], "الواو هنا واو المعية بمعنى «مع»، ولا يصح العطف لأن النيل لا يسير، فالاسم بعدها منصوب على أنه مفعول معه."] },

  { id: "nht-050", s: "nahw", g: 3, d: 3, t: ["badal"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-badal",
    en: ["In the sentence أَكَلْتُ الرَّغِيفَ ثُلُثَهُ, what kind of badal is ثُلُثَهُ?", ["Badal of a part from the whole", "Badal of the whole from the whole", "Badal of inclusion (ishtimāl)", "Badal of error (ghalaṭ)"], "A third is part of the loaf, so it is badal baʿḍ min kull. Such a badal normally carries a pronoun referring back to the whole, here the -hu."],
    de: ["Welche Art Badal ist ثُلُثَهُ im Satz أَكَلْتُ الرَّغِيفَ ثُلُثَهُ?", ["Badal des Teils vom Ganzen", "Badal des Ganzen vom Ganzen", "Badal der Einbeziehung (ištimāl)", "Badal des Versehens (ġalaṭ)"], "Ein Drittel ist ein Teil des Brotes, also badal baʿḍ min kull. Ein solcher Badal trägt in der Regel ein rückverweisendes Pronomen, hier -hu."],
    ar: ["ما نوع البدل في «ثلثَه» من جملة: أكلتُ الرغيفَ ثلثَه؟", ["بدل بعض من كل", "بدل كل من كل", "بدل اشتمال", "بدل غلط"], "الثلث جزء من الرغيف فهو بدل بعض من كل، ويشترط فيه غالبًا ضمير يعود على المبدل منه وهو الهاء."] },

  { id: "nht-051", s: "nahw", g: 3, d: 3, t: ["tawkid"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-tawkīd",
    en: ["In the sentence جَاءَ المُدِيرُ نَفْسُهُ, what is نَفْسُهُ?", ["Tawkīd maʿnawī", "Tawkīd lafẓī", "Badal", "Naʿt"], "Nafs, ʿayn, kull, ajmaʿ and their like are words of semantic emphasis: they remove the possibility that only a messenger of the director came. Lafẓī emphasis would repeat the same word."],
    de: ["Was ist نَفْسُهُ im Satz جَاءَ المُدِيرُ نَفْسُهُ?", ["Tawkīd maʿnawī", "Tawkīd lafẓī", "Badal", "Naʿt"], "Nafs, ʿain, kull, aǧmaʿ und ähnliche sind Wörter der inhaltlichen Bekräftigung: Sie schließen aus, dass nur ein Bote des Direktors kam. Die lafẓī-Bekräftigung wiederholt dasselbe Wort."],
    ar: ["ما إعراب «نفسُه» في جملة: جاءَ المديرُ نفسُه؟", ["توكيد معنوي", "توكيد لفظي", "بدل", "نعت"], "النفس والعين وكل وأجمع ألفاظ التوكيد المعنوي، ترفع احتمال أن يكون الجائي رسول المدير، وأما اللفظي فبتكرار اللفظ نفسه."] },

  { id: "nht-052", s: "nahw", g: 3, d: 3, t: ["conditional", "jazm"], src: "Ibn Hishām, Sharḥ Qaṭr al-Nadā, on the particles that put two verbs in jazm",
    en: ["In the sentence إِنْ تَجْتَهِدْ تَنْجَحْ, what is تَنْجَحْ?", ["Jawāb al-sharṭ, majzūm", "Fiʿl al-sharṭ, majzūm", "A present verb, marfūʿ", "A ḥāl in the place of naṣb"], "In is a conditional particle that puts two verbs in jazm: the first (tajtahid) is the condition, the second (tanjaḥ) its answer and consequence."],
    de: ["Was ist تَنْجَحْ im Satz إِنْ تَجْتَهِدْ تَنْجَحْ?", ["Ǧawāb aš-šarṭ, maǧzūm", "Fiʿl aš-šarṭ, maǧzūm", "Ein Präsensverb, marfūʿ", "Ein Ḥāl an Stelle des naṣb"], "In ist eine Bedingungspartikel, die zwei Verben in den ǧazm setzt: das erste (taǧtahid) ist die Bedingung, das zweite (tanǧaḥ) ihre Antwort und Folge."],
    ar: ["ما إعراب «تنجحْ» في جملة: إنْ تجتهدْ تنجحْ؟", ["جواب الشرط مجزوم", "فعل الشرط مجزوم", "فعل مضارع مرفوع", "حال في محل نصب"], "«إن» حرف شرط يجزم فعلين: الأول «تجتهد» فعل الشرط، والثاني «تنجح» جوابه وجزاؤه."] },

  { id: "nht-053", s: "nahw", g: 3, d: 4, t: ["conditional"], src: "Ibn Hishām, Mughnī al-Labīb, on the letter fāʾ",
    en: ["Why must the answer in إِنْ جَاءَكَ ضَيْفٌ فَأَكْرِمْهُ be introduced by fāʾ?", ["The answer is an imperative, a request", "The condition is a past-tense verb", "The answer is a past-tense verb", "In is always followed by fāʾ"], "The fāʾ is required when the answer cannot itself stand as a condition, for example a nominal sentence, a request (amr, nahy), or a verb with lan, qad or sīn. A past verb as condition needs no fāʾ."],
    de: ["Warum muss die Antwort in إِنْ جَاءَكَ ضَيْفٌ فَأَكْرِمْهُ mit fāʾ eingeleitet werden?", ["Die Antwort ist ein Imperativ, eine Aufforderung", "Die Bedingung ist ein Perfekt", "Die Antwort ist ein Perfekt", "Nach in folgt immer fāʾ"], "Das fāʾ ist nötig, wenn die Antwort selbst nicht als Bedingung stehen kann, etwa ein Nominalsatz, eine Aufforderung (Befehl, Verbot) oder ein Verb mit lan, qad oder sa-. Ein Perfekt als Bedingung verlangt kein fāʾ."],
    ar: ["لماذا وجب اقتران الجواب بالفاء في: إنْ جاءكَ ضيفٌ فأكرمْه؟", ["لأن الجواب جملة طلبية (أمر)", "لأن فعل الشرط ماضٍ", "لأن الجواب فعل ماضٍ", "لأن «إن» يتبعها الفاء دائمًا"], "تجب الفاء إذا كان الجواب لا يصلح أن يكون شرطًا، كالجملة الاسمية والطلبية والفعل المقرون بلن أو قد أو السين، وكون الشرط ماضيًا لا يوجبها."] },

  { id: "nht-054", s: "nahw", g: 3, d: 3, t: ["weak-verbs"], src: "al-Ḥamlāwī, Shadhā al-ʿArf fī Fann al-Ṣarf, on the sound and weak verb",
    en: ["How is the verb وَجَدَ classified in ṣarf?", ["Mithāl", "Ajwaf", "Nāqiṣ", "Mahmūz"], "A verb whose first radical is a weak letter (wāw or yāʾ) is called mithāl. Ajwaf has a weak middle radical, nāqiṣ a weak final one, and mahmūz contains a hamza."],
    de: ["Wie wird das Verb وَجَدَ in der Formenlehre eingeordnet?", ["Miṯāl", "Aǧwaf", "Nāqiṣ", "Mahmūz"], "Ein Verb, dessen erster Radikal schwach ist (Wāw oder Yāʾ), heißt miṯāl. Aǧwaf hat einen schwachen mittleren, nāqiṣ einen schwachen letzten Radikal, und mahmūz enthält eine Hamza."],
    ar: ["ما نوع الفعل «وجد» في علم الصرف؟", ["مثال", "أجوف", "ناقص", "مهموز"], "ما كانت فاؤه حرف علة (واوًا أو ياءً) يسمى مثالًا، والأجوف ما اعتلت عينه، والناقص ما اعتلت لامه، والمهموز ما كان أحد أصوله همزة."] },

  { id: "nht-055", s: "nahw", g: 3, d: 3, t: ["nida", "mabni-murab"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb al-munādā",
    en: ["In the call يَا خَالِدُ, what is the iʿrāb of خَالِدُ?", ["Mabnī on ḍamma, in the position of naṣb", "Marfūʿ with an apparent ḍamma", "Manṣūb with an apparent fatḥa", "Mubtadaʾ, marfūʿ with ḍamma"], "A single proper name in the vocative is built on what it would have in rafʿ, here a ḍamma without tanwīn, but its position is naṣb because it is the object of an implied \"I call\"."],
    de: ["Wie lautet der Iʿrāb von خَالِدُ im Anruf يَا خَالِدُ?", ["Mabnī auf Ḍamma, an Stelle des naṣb", "Marfūʿ mit sichtbarer Ḍamma", "Manṣūb mit sichtbarer Fatḥa", "Mubtadaʾ, marfūʿ mit Ḍamma"], "Ein einzelner Eigenname im Vokativ ist auf das gebaut, womit er im rafʿ stünde, hier Ḍamma ohne Tanwīn; seine Stelle ist aber naṣb, da er Objekt eines gedachten „ich rufe“ ist."],
    ar: ["ما إعراب «خالدُ» في: يا خالدُ؟", ["منادى مبني على الضم في محل نصب", "مرفوع بالضمة الظاهرة", "منصوب بالفتحة الظاهرة", "مبتدأ مرفوع بالضمة"], "العلم المفرد في النداء يُبنى على ما يُرفع به، وهو هنا الضم بلا تنوين، وهو في محل نصب لأنه مفعول به لفعل نداء محذوف تقديره أدعو."] },

  { id: "nht-056", s: "nahw", g: 3, d: 3, t: ["weak-verbs"], src: "al-Ḥamlāwī, Shadhā al-ʿArf fī Fann al-Ṣarf, on the sound and weak verb",
    en: ["Which of these verbs is nāqiṣ (weak in its final radical)?", ["رَمَى", "وَعَدَ", "قَالَ", "كَتَبَ"], "Ramā goes back to the root r-m-y, with a weak final radical. Waʿada is mithāl, qāla is ajwaf (root q-w-l), and kataba is sound."],
    de: ["Welches dieser Verben ist nāqiṣ (schwach im letzten Radikal)?", ["رَمَى", "وَعَدَ", "قَالَ", "كَتَبَ"], "Ramā geht auf die Wurzel r-m-y zurück, mit schwachem letztem Radikal. Waʿada ist miṯāl, qāla ist aǧwaf (Wurzel q-w-l), und kataba ist gesund."],
    ar: ["أيّ هذه الأفعال ناقص (معتل اللام)؟", ["رمى", "وعد", "قال", "كتب"], "«رمى» أصله من (ر م ي) فلامه حرف علة، و«وعد» مثال، و«قال» أجوف من (ق و ل)، و«كتب» صحيح سالم."] },

  { id: "nht-057", s: "nahw", g: 3, d: 4, t: ["mizan", "weak-verbs"], src: "al-Ḥamlāwī, Shadhā al-ʿArf fī Fann al-Ṣarf, on the mīzān ṣarfī",
    en: ["What is the morphological pattern (mīzān) of the verb قَالَ?", ["فَعَلَ", "فَالَ", "فَاعَ", "فَعْلَ"], "The mīzān follows the original letters: qāla comes from qawala, whose voweled wāw after a fatḥa turned into alif. So it is weighed faʿala, with the ʿayn standing for the changed wāw."],
    de: ["Wie lautet das morphologische Muster (mīzān) des Verbs قَالَ?", ["فَعَلَ", "فَالَ", "فَاعَ", "فَعْلَ"], "Der Mīzān richtet sich nach den ursprünglichen Buchstaben: qāla stammt von qawala, dessen vokalisiertes Wāw nach Fatḥa zu Alif wurde. Es wird daher faʿala gewogen; das ʿAin steht für das veränderte Wāw."],
    ar: ["ما وزن الفعل «قال» في الميزان الصرفي؟", ["فَعَلَ", "فالَ", "فاعَ", "فَعْلَ"], "يوزن الفعل بأصوله، و«قال» أصله «قَوَلَ» تحركت الواو وانفتح ما قبلها فقُلبت ألفًا، فوزنه «فَعَلَ» والعين مقابلة للواو المنقلبة."] },

  { id: "nht-058", s: "nahw", g: 3, d: 3, t: ["case-signs", "mabni-murab"], src: "Ibn Hishām, Sharḥ Qaṭr al-Nadā, on estimated case signs",
    en: ["In the sentence جَاءَ الفَتَى, how is الفَتَى marked as marfūʿ?", ["By an estimated ḍamma, since it cannot be pronounced", "By an apparent ḍamma on the alif", "By the alif as a substitute sign", "It is mabnī and has no rafʿ"], "Al-fatā is ism maqṣūr, ending in a fixed alif. All three case vowels are estimated on it because pronouncing them on the alif is impossible (taʿadhdhur)."],
    de: ["Wie zeigt الفَتَى im Satz جَاءَ الفَتَى den rafʿ?", ["Durch eine angenommene Ḍamma, da sie unaussprechbar ist", "Durch eine sichtbare Ḍamma auf dem Alif", "Durch das Alif als Ersatzzeichen", "Es ist mabnī und hat keinen rafʿ"], "Al-fatā ist ein ism maqṣūr mit festem Alif am Ende. Alle drei Kasusvokale werden angenommen, weil ihre Aussprache auf dem Alif unmöglich ist (taʿaḏḏur)."],
    ar: ["ما علامة رفع «الفتى» في جملة: جاءَ الفتى؟", ["ضمة مقدرة منع من ظهورها التعذر", "ضمة ظاهرة على الألف", "الألف نيابة عن الضمة", "لا رفع فيه لأنه مبني"], "«الفتى» اسم مقصور آخره ألف لازمة، فتُقدَّر عليه الحركات الثلاث للتعذر، وهو معرب لا مبني."] },

  { id: "nht-059", s: "nahw", g: 3, d: 4, t: ["broken-plurals"], src: "Ibn ʿAqīl, Sharḥ Alfiyyat Ibn Mālik, bāb jamʿ al-taksīr",
    en: ["Which of these is one of the patterns of the plural of paucity (jamʿ al-qilla)?", ["أَفْعَال", "فُعُول", "فِعَال", "مَفَاعِيل"], "The plurals of paucity, used in principle for three to ten, have four patterns: afʿul, afʿāl, afʿila and fiʿla. Fuʿūl, fiʿāl and mafāʿīl are plurals of multitude."],
    de: ["Welches ist eines der Muster des Plurals der Wenigkeit (ǧamʿ al-qilla)?", ["أَفْعَال", "فُعُول", "فِعَال", "مَفَاعِيل"], "Die Plurale der Wenigkeit, grundsätzlich für drei bis zehn, haben vier Muster: afʿul, afʿāl, afʿila und fiʿla. Fuʿūl, fiʿāl und mafāʿīl sind Plurale der Vielheit."],
    ar: ["أيّ هذه الأوزان من أوزان جمع القلة؟", ["أفعال", "فُعول", "فِعال", "مفاعيل"], "لجمع القلة -وهو في الأصل لما بين الثلاثة والعشرة- أربعة أوزان: أفعُل وأفعال وأفعِلة وفِعْلة، وأما فُعول وفِعال ومفاعيل فمن جموع الكثرة."] },

  { id: "nht-060", s: "nahw", g: 3, d: 4, t: ["mamnu-min-al-sarf", "broken-plurals"], src: "Ibn Hishām, Sharḥ Qaṭr al-Nadā, bāb mā lā yanṣarif",
    en: ["In the sentence صَلَّيْتُ فِي مَسَاجِدَ كَثِيرَةٍ, why is مَسَاجِدَ majrūr with a fatḥa?", ["It has the pattern of muntahā al-jumūʿ", "It is a sound feminine plural", "It is muḍāf to the following noun", "It is a foreign proper name"], "Masājid is on the pattern mafāʿil, a \"furthest plural\" form, which alone is enough to make a noun mamnūʿ min al-ṣarf. Without al- or iḍāfa it takes a fatḥa in jarr and no tanwīn."],
    de: ["Warum ist مَسَاجِدَ im Satz صَلَّيْتُ فِي مَسَاجِدَ كَثِيرَةٍ mit Fatḥa maǧrūr?", ["Es hat das Muster muntahā l-ǧumūʿ", "Es ist ein gesunder femininer Plural", "Es ist an das folgende Nomen annektiert", "Es ist ein fremder Eigenname"], "Masāǧid folgt dem Muster mafāʿil, einer Form des „äußersten Plurals“, die allein schon diptotisch macht. Ohne al- oder Iḍāfa steht es im ǧarr mit Fatḥa und ohne Tanwīn."],
    ar: ["لماذا جُرّت «مساجدَ» بالفتحة في جملة: صليتُ في مساجدَ كثيرةٍ؟", ["لأنها على صيغة منتهى الجموع", "لأنها جمع مؤنث سالم", "لأنها مضافة إلى ما بعدها", "لأنها علم أعجمي"], "«مساجد» على وزن «مفاعل» وهي صيغة منتهى الجموع، وهي علة تكفي وحدها لمنع الصرف، فتُجر بالفتحة ولا تنوَّن ما لم تقترن بأل أو تُضف."] },

  { id: "nht-061", s: "nahw", g: 3, d: 4, t: ["la-nafiya", "mabni-murab"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb lā",
    en: ["In the sentence لَا رَجُلَ فِي الدَّارِ, what is the iʿrāb of رَجُلَ?", ["Ism of lā, mabnī on fatḥa", "Ism of lā, manṣūb with tanwīn", "Mubtadaʾ, marfūʿ", "Mafʿūl bihi, manṣūb"], "Lā that negates the whole genus governs like inna. When its ism is a single indefinite noun directly after it, the ism is mabnī on fatḥa, without tanwīn, in the position of naṣb."],
    de: ["Wie lautet der Iʿrāb von رَجُلَ im Satz لَا رَجُلَ فِي الدَّارِ?", ["Ism von lā, mabnī auf Fatḥa", "Ism von lā, manṣūb mit Tanwīn", "Mubtadaʾ, marfūʿ", "Mafʿūl bihi, manṣūb"], "Das lā, das die ganze Gattung verneint, wirkt wie inna. Ist sein Ism ein einzelnes unbestimmtes Nomen direkt danach, ist er mabnī auf Fatḥa, ohne Tanwīn, an Stelle des naṣb."],
    ar: ["ما إعراب «رجلَ» في جملة: لا رجلَ في الدارِ؟", ["اسم لا مبني على الفتح", "اسم لا منصوب منوَّن", "مبتدأ مرفوع", "مفعول به منصوب"], "«لا» النافية للجنس تعمل عمل إنّ، فإذا كان اسمها مفردًا نكرة متصلًا بها بُني على الفتح بلا تنوين في محل نصب."] },

  { id: "nht-062", s: "nahw", g: 3, d: 3, t: ["zanna-sisters", "mafulat"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, bāb ẓanantu wa-akhawātuhā",
    en: ["In the sentence ظَنَنْتُ الجَوَّ بَارِدًا, what is بَارِدًا?", ["Second object of ẓanantu", "Ḥāl of al-jaww", "Naʿt of al-jaww", "Tamyīz, manṣūb"], "Ẓanna and its sisters enter a nominal sentence and make both parts manṣūb as two objects: al-jaww is the first, bāridan the second. It cannot be a naʿt, since it is indefinite after a definite noun."],
    de: ["Was ist بَارِدًا im Satz ظَنَنْتُ الجَوَّ بَارِدًا?", ["Zweites Objekt von ẓanantu", "Ḥāl von al-ǧaww", "Naʿt von al-ǧaww", "Tamyīz, manṣūb"], "Ẓanna und seine Schwestern treten vor einen Nominalsatz und setzen beide Teile als zwei Objekte in den naṣb: al-ǧaww ist das erste, bāridan das zweite. Ein Naʿt ist es nicht, da es unbestimmt nach einem bestimmten Nomen steht."],
    ar: ["ما إعراب «باردًا» في جملة: ظننتُ الجوَّ باردًا؟", ["مفعول به ثانٍ لظنّ", "حال من الجو", "نعت للجو", "تمييز منصوب"], "ظنّ وأخواتها تدخل على المبتدأ والخبر فتنصبهما مفعولين، فـ«الجو» مفعول أول و«باردًا» مفعول ثانٍ، ولا يكون نعتًا لأنه نكرة والمنعوت معرفة."] },

  { id: "nht-063", s: "nahw", g: 3, d: 4, t: ["numbers", "tamyiz"], src: "Ibn ʿAqīl, Sharḥ Alfiyyat Ibn Mālik, bāb al-ʿadad",
    en: ["Which of these phrases is grammatically correct?", ["عِنْدِي خَمْسَةُ أَقْلَامٍ", "عِنْدِي خَمْسُ أَقْلَامٍ", "عِنْدِي خَمْسَةُ قَلَمًا", "عِنْدِي خَمْسَةُ قَلَمٍ"], "The numbers three to ten take the opposite gender of the counted noun and their tamyīz is a majrūr plural. Qalam is masculine, so the number is khamsatu, followed by aqlāmin."],
    de: ["Welche dieser Wendungen ist grammatisch richtig?", ["عِنْدِي خَمْسَةُ أَقْلَامٍ", "عِنْدِي خَمْسُ أَقْلَامٍ", "عِنْدِي خَمْسَةُ قَلَمًا", "عِنْدِي خَمْسَةُ قَلَمٍ"], "Die Zahlen drei bis zehn nehmen das entgegengesetzte Geschlecht des Gezählten an, und ihr Tamyīz ist ein Plural im ǧarr. Qalam ist maskulin, daher ḫamsatu, gefolgt von aqlāmin."],
    ar: ["أيّ هذه العبارات صحيحة نحويًا؟", ["عندي خمسةُ أقلامٍ", "عندي خمسُ أقلامٍ", "عندي خمسةُ قلمًا", "عندي خمسةُ قلمٍ"], "الأعداد من الثلاثة إلى العشرة تخالف المعدود في التذكير والتأنيث، وتمييزها جمع مجرور، و«قلم» مذكر فيقال: خمسة أقلام."] },

  { id: "nht-064", s: "nahw", g: 3, d: 4, t: ["weak-verbs"], src: "al-Ḥamlāwī, Shadhā al-ʿArf fī Fann al-Ṣarf, on the mithāl verb",
    en: ["What is the present tense of the form I verb وَصَلَ (to arrive)?", ["يَصِلُ", "يَوْصِلُ", "يُوصِلُ", "يَوْصُلُ"], "In a mithāl wāwī verb of the pattern faʿala–yafʿilu, the wāw drops in the present: waṣala gives yaṣilu, as waʿada gives yaʿidu. Yūṣilu is the present of form IV awṣala."],
    de: ["Wie lautet das Präsens des Grundstamm-Verbs وَصَلَ (ankommen)?", ["يَصِلُ", "يَوْصِلُ", "يُوصِلُ", "يَوْصُلُ"], "Bei einem miṯāl-Verb mit Wāw nach dem Muster faʿala–yafʿilu fällt das Wāw im Präsens weg: waṣala wird yaṣilu, wie waʿada zu yaʿidu. Yūṣilu ist das Präsens des IV. Stammes auṣala."],
    ar: ["ما مضارع الفعل الثلاثي «وَصَلَ»؟", ["يَصِلُ", "يَوْصِلُ", "يُوصِلُ", "يَوْصُلُ"], "المثال الواوي من باب فَعَل يفعِل تُحذف واوه في المضارع، فيقال: وصل يصل كوعد يعد، وأما «يوصل» فمضارع الرباعي «أوصل»."] },

  { id: "nht-065", s: "nahw", g: 4, d: 4, t: ["classical-works", "grammar-schools"], src: "al-Sīrāfī, Akhbār al-Naḥwiyyīn al-Baṣriyyīn, on Sībawayh",
    en: ["Which teacher of Sībawayh is quoted more than any other in al-Kitāb?", ["al-Khalīl ibn Aḥmad al-Farāhīdī", "ʿAlī ibn Ḥamza al-Kisāʾī", "Yaḥyā ibn Ziyād al-Farrāʾ", "Muḥammad ibn Yazīd al-Mubarrad"], "Sībawayh's chief teacher was al-Khalīl, founder of the science of prosody, whose views fill al-Kitāb. Al-Kisāʾī and al-Farrāʾ were Kūfan contemporaries and rivals, and al-Mubarrad belongs to a later Baṣran generation."],
    de: ["Welcher Lehrer Sībawaihs wird im Kitāb häufiger zitiert als jeder andere?", ["al-Ḫalīl ibn Aḥmad al-Farāhīdī", "ʿAlī ibn Ḥamza al-Kisāʾī", "Yaḥyā ibn Ziyād al-Farrāʾ", "Muḥammad ibn Yazīd al-Mubarrad"], "Sībawaihs Hauptlehrer war al-Ḫalīl, Begründer der Metrik, dessen Ansichten den Kitāb füllen. Al-Kisāʾī und al-Farrāʾ waren kufische Zeitgenossen und Rivalen, al-Mubarrad gehört einer späteren basrischen Generation an."],
    ar: ["مَن شيخ سيبويه الذي أكثر النقل عنه في «الكتاب»؟", ["الخليل بن أحمد الفراهيدي", "علي بن حمزة الكسائي", "يحيى بن زياد الفراء", "محمد بن يزيد المبرد"], "أكثر سيبويه في الكتاب من النقل عن شيخه الخليل بن أحمد واضع علم العروض، وأما الكسائي والفراء فكوفيان معاصران له، والمبرد من طبقة بصرية متأخرة."] },

  { id: "nht-066", s: "nahw", g: 4, d: 4, t: ["grammar-schools"], src: "al-Zubaydī, Ṭabaqāt al-Naḥwiyyīn wa-l-Lughawiyyīn",
    en: ["Which pair are both leading grammarians of the Kūfan school?", ["al-Kisāʾī and al-Farrāʾ", "Sībawayh and al-Akhfash al-Awsaṭ", "al-Mubarrad and al-Zajjāj", "al-Khalīl and Yūnus ibn Ḥabīb"], "Al-Kisāʾī, also one of the seven Quran readers, and his student al-Farrāʾ are the pillars of Kūfan grammar. All the other names are Baṣrans."],
    de: ["Welches Paar sind beide führende Grammatiker der kufischen Schule?", ["al-Kisāʾī und al-Farrāʾ", "Sībawaih und al-Aḫfaš al-Ausaṭ", "al-Mubarrad und az-Zaǧǧāǧ", "al-Ḫalīl und Yūnus ibn Ḥabīb"], "Al-Kisāʾī, zugleich einer der sieben Koranleser, und sein Schüler al-Farrāʾ sind die Säulen der kufischen Grammatik. Alle übrigen Namen sind Basrier."],
    ar: ["أيّ الزوجين من أئمة المذهب الكوفي في النحو؟", ["الكسائي والفراء", "سيبويه والأخفش الأوسط", "المبرد والزجاج", "الخليل ويونس بن حبيب"], "الكسائي -وهو أحد القراء السبعة- وتلميذه الفراء عمدة النحو الكوفي، وأما الباقون فبصريون."] },

  { id: "nht-067", s: "nahw", g: 4, d: 5, t: ["grammar-schools", "masdar"], src: "Abū al-Barakāt al-Anbārī, al-Inṣāf fī Masāʾil al-Khilāf, on the origin of derivation",
    en: ["Which statement correctly describes the dispute over the origin of derivation (aṣl al-ishtiqāq)?", ["Baṣrans: the maṣdar is the origin; Kūfans: the verb", "Baṣrans: the verb is the origin; Kūfans: the maṣdar", "Both schools hold the verb is the origin", "Both schools hold the participle is the origin"], "The Baṣrans argued that the maṣdar, which names the event without time, is the source from which verb and participles derive. The Kūfans held that the maṣdar comes from the verb, citing among other things that it follows the verb in soundness and weakness."],
    de: ["Welche Aussage beschreibt den Streit um den Ursprung der Ableitung (aṣl al-ištiqāq) richtig?", ["Basrier: der Maṣdar ist der Ursprung; Kufier: das Verb", "Basrier: das Verb ist der Ursprung; Kufier: der Maṣdar", "Beide Schulen sehen das Verb als Ursprung", "Beide Schulen sehen das aktive Partizip als Ursprung"], "Die Basrier argumentierten, der Maṣdar, der das Geschehen ohne Zeit benennt, sei die Quelle, aus der Verb und Partizipien abgeleitet werden. Die Kufier sahen den Maṣdar als vom Verb abgeleitet, unter anderem, weil er dem Verb in Gesundheit und Schwäche folgt."],
    ar: ["ما القول الصحيح في الخلاف في أصل الاشتقاق؟", ["البصريون: المصدر أصل، والكوفيون: الفعل أصل", "البصريون: الفعل أصل، والكوفيون: المصدر أصل", "اتفق الفريقان على أن الفعل هو الأصل", "اتفق الفريقان على أن اسم الفاعل هو الأصل"], "ذهب البصريون إلى أن المصدر أصل يُشتق منه الفعل وسائر المشتقات لدلالته على الحدث المجرد من الزمان، وذهب الكوفيون إلى أن المصدر مشتق من الفعل، واحتجوا بأمور منها أنه يصح بصحته ويعتل باعتلاله."] },

  { id: "nht-068", s: "nahw", g: 4, d: 4, t: ["classical-works", "grammar-schools"], src: "Abū al-Barakāt al-Anbārī, al-Inṣāf fī Masāʾil al-Khilāf bayna al-Naḥwiyyīn al-Baṣriyyīn wa-l-Kūfiyyīn",
    en: ["Who wrote al-Inṣāf, the classic work on the points of disagreement between the Baṣran and Kūfan grammarians?", ["Abū al-Barakāt al-Anbārī", "Abū al-Fatḥ ibn Jinnī", "Abū al-Qāsim al-Zajjājī", "Abū Bakr ibn al-Sarrāj"], "Abū al-Barakāt al-Anbārī set out over a hundred disputed questions in al-Inṣāf, giving the arguments of both schools and usually siding with the Baṣrans. Ibn Jinnī is known for al-Khaṣāʾiṣ."],
    de: ["Wer verfasste al-Inṣāf, das klassische Werk über die Streitfragen zwischen basrischen und kufischen Grammatikern?", ["Abū l-Barakāt al-Anbārī", "Abū l-Fatḥ ibn Ǧinnī", "Abū l-Qāsim az-Zaǧǧāǧī", "Abū Bakr ibn as-Sarrāǧ"], "Abū l-Barakāt al-Anbārī legte in al-Inṣāf über hundert Streitfragen dar, mit den Argumenten beider Schulen, meist zugunsten der Basrier. Ibn Ǧinnī ist für al-Ḫaṣāʾiṣ bekannt."],
    ar: ["مَن صاحب كتاب «الإنصاف في مسائل الخلاف بين النحويين البصريين والكوفيين»؟", ["أبو البركات الأنباري", "أبو الفتح ابن جني", "أبو القاسم الزجاجي", "أبو بكر ابن السراج"], "عرض أبو البركات الأنباري في الإنصاف أكثر من مئة مسألة خلافية بحجج الفريقين، وكان في الغالب يرجّح مذهب البصريين، وأما ابن جني فصاحب «الخصائص»."] },

  { id: "nht-069", s: "nahw", g: 4, d: 5, t: ["grammar-schools", "nominal-sentence"], src: "Ibn Hishām, Mughnī al-Labīb, on ḍamīr al-faṣl",
    en: ["The pronoun that Kūfans call ʿimād (support), as in زَيْدٌ هُوَ القَائِمُ, is called by the Baṣrans:", ["Ḍamīr al-faṣl (pronoun of separation)", "Ḍamīr al-shaʾn (pronoun of the matter)", "Ḍamīr munfaṣil mubtadaʾ (detached subject)", "Ḍamīr mustatir (hidden pronoun)"], "The Baṣrans call it faṣl because it separates khabar from naʿt, making clear that al-qāʾim is the predicate; the Kūfans call it ʿimād because the speaker leans on it. The pronoun of the matter is a different construction, which Kūfans call al-ḍamīr al-majhūl."],
    de: ["Das Pronomen, das die Kufier ʿimād (Stütze) nennen, wie in زَيْدٌ هُوَ القَائِمُ, nennen die Basrier:", ["Ḍamīr al-faṣl (Trennungspronomen)", "Ḍamīr aš-šaʾn (Pronomen der Sache)", "Ḍamīr munfaṣil mubtadaʾ (getrenntes Subjekt)", "Ḍamīr mustatir (verborgenes Pronomen)"], "Die Basrier nennen es faṣl, weil es den Ḫabar vom Naʿt trennt und klarstellt, dass al-qāʾim Prädikat ist; die Kufier nennen es ʿimād, weil sich der Sprecher darauf stützt. Das Pronomen der Sache ist eine andere Konstruktion, die die Kufier aḍ-ḍamīr al-maǧhūl nennen."],
    ar: ["الضمير الذي يسميه الكوفيون «عمادًا» نحو: زيدٌ هو القائمُ، يسميه البصريون:", ["ضمير الفصل", "ضمير الشأن", "ضميرًا منفصلًا مبتدأً", "ضميرًا مستترًا"], "سماه البصريون فصلًا لأنه يفصل بين الخبر والنعت فيتبيّن أن «القائم» خبر، وسماه الكوفيون عمادًا لاعتماد المتكلم عليه، وأما ضمير الشأن فباب آخر يسميه الكوفيون الضمير المجهول."] },

  { id: "nht-070", s: "nahw", g: 4, d: 4, t: ["classical-works"], src: "Ibn Hishām, Qaṭr al-Nadā wa-Ball al-Ṣadā",
    en: ["Who wrote Qaṭr al-Nadā wa-Ball al-Ṣadā together with his own commentary on it?", ["Ibn Hishām al-Anṣārī", "Ibn ʿAqīl", "Ibn Mālik al-Ṭāʾī", "Jalāl al-Dīn al-Suyūṭī"], "Qaṭr al-Nadā is one of Ibn Hishām's teaching texts, which he explained himself in Sharḥ Qaṭr al-Nadā. He also wrote Shudhūr al-Dhahab and Mughnī al-Labīb. Ibn ʿAqīl is known for his commentary on the Alfiyya."],
    de: ["Wer verfasste Qaṭr an-Nadā wa-Ball aṣ-Ṣadā und dazu einen eigenen Kommentar?", ["Ibn Hišām al-Anṣārī", "Ibn ʿAqīl", "Ibn Mālik aṭ-Ṭāʾī", "Ǧalāl ad-Dīn as-Suyūṭī"], "Qaṭr an-Nadā ist einer der Lehrtexte Ibn Hišāms, den er selbst in Šarḥ Qaṭr an-Nadā erklärte. Von ihm stammen auch Šuḏūr aḏ-Ḏahab und Muġnī l-Labīb. Ibn ʿAqīl ist für seinen Kommentar zur Alfiyya bekannt."],
    ar: ["مَن صاحب «قطر الندى وبل الصدى» وشرحه؟", ["ابن هشام الأنصاري", "ابن عقيل", "ابن مالك الطائي", "جلال الدين السيوطي"], "قطر الندى من متون ابن هشام التعليمية وقد شرحه بنفسه، وله أيضًا «شذور الذهب» و«مغني اللبيب»، وأما ابن عقيل فمشهور بشرحه على الألفية."] },

  { id: "nht-071", s: "nahw", g: 4, d: 4, t: ["classical-works"], src: "Ibn Mālik, al-Khulāṣa (Alfiyyat Ibn Mālik)",
    en: ["In which poetic metre is the Alfiyya of Ibn Mālik composed?", ["Rajaz", "Ṭawīl", "Basīṭ", "Kāmil"], "Like most didactic poems (manẓūmāt), the Alfiyya is in rajaz, whose flexible metre and rhyming couplets make it easy to memorise. Its roughly one thousand lines give it its name."],
    de: ["In welchem Versmaß ist die Alfiyya von Ibn Mālik verfasst?", ["Raǧaz", "Ṭawīl", "Basīṭ", "Kāmil"], "Wie die meisten Lehrgedichte (manẓūmāt) ist die Alfiyya im Raǧaz verfasst, dessen bewegliches Versmaß und paarweise Reime das Auswendiglernen erleichtern. Ihre rund tausend Verse geben ihr den Namen."],
    ar: ["مِن أيّ بحر نُظمت ألفية ابن مالك؟", ["الرجز", "الطويل", "البسيط", "الكامل"], "الألفية من بحر الرجز كأكثر المنظومات التعليمية، لسهولته وتقفية شطريه مما ييسر الحفظ، وسميت ألفية لأن أبياتها نحو ألف بيت."] },

  { id: "nht-072", s: "nahw", g: 4, d: 5, t: ["classical-works"], src: "Ibn Mālik, al-Khulāṣa (Alfiyyat Ibn Mālik), introduction",
    en: ["Which earlier grammar poem does Ibn Mālik name in the introduction to his Alfiyya, claiming to surpass it while acknowledging its precedence?", ["The Alfiyya of Ibn Muʿṭī", "The Ājurrūmiyya of Ibn Ājurrūm", "The Mulḥat al-Iʿrāb of al-Ḥarīrī", "The Kāfiya of Ibn al-Ḥājib"], "Ibn Mālik says his poem surpasses the Alfiyya of Ibn Muʿṭī, then concedes that Ibn Muʿṭī has the merit of precedence and prays for him. The Ājurrūmiyya was written after Ibn Mālik, and the Kāfiya is prose."],
    de: ["Welches frühere Grammatikgedicht nennt Ibn Mālik in der Einleitung seiner Alfiyya, das er zu übertreffen beansprucht, dessen Vorrang er aber anerkennt?", ["Die Alfiyya von Ibn Muʿṭī", "Die Āǧurrūmiyya von Ibn Āǧurrūm", "Die Mulḥat al-Iʿrāb von al-Ḥarīrī", "Die Kāfiya von Ibn al-Ḥāǧib"], "Ibn Mālik sagt, sein Gedicht übertreffe die Alfiyya von Ibn Muʿṭī, räumt dann aber ein, dass Ibn Muʿṭī den Vorzug des Vorrangs hat, und bittet für ihn. Die Āǧurrūmiyya entstand nach Ibn Mālik, und die Kāfiya ist Prosa."],
    ar: ["أيّ منظومة نحوية سابقة ذكرها ابن مالك في مقدمة ألفيته فذكر أنها تفوقها مع اعترافه بسبقها؟", ["ألفية ابن معطي", "الآجرومية لابن آجروم", "ملحة الإعراب للحريري", "الكافية لابن الحاجب"], "ذكر ابن مالك أن ألفيته فائقة ألفية ابن معطي، ثم اعترف له بفضل السبق ودعا له، وأما الآجرومية فمتأخرة عن ابن مالك، والكافية منثورة."] },

  { id: "nht-073", s: "nahw", g: 4, d: 5, t: ["la-nafiya", "mabni-murab"], src: "Ibn ʿAqīl, Sharḥ Alfiyyat Ibn Mālik, bāb lā allatī li-nafy al-jins",
    en: ["In the sentence لَا طَالِبَ عِلْمٍ خَاسِرٌ, what is the iʿrāb of طَالِبَ?", ["Ism of lā, muʿrab and manṣūb", "Ism of lā, mabnī on fatḥa", "Mubtadaʾ, marfūʿ", "Ḥāl, manṣūb"], "The ism of lā al-nāfiya li-l-jins is mabnī only when it is a single word (mufrad). When it is muḍāf, as here, or resembles a muḍāf, it is declinable and manṣūb with an apparent fatḥa; khāsirun is the khabar."],
    de: ["Wie lautet der Iʿrāb von طَالِبَ im Satz لَا طَالِبَ عِلْمٍ خَاسِرٌ?", ["Ism von lā, muʿrab und manṣūb", "Ism von lā, mabnī auf Fatḥa", "Mubtadaʾ, marfūʿ", "Ḥāl, manṣūb"], "Der Ism des gattungsverneinenden lā ist nur mabnī, wenn er ein Einzelwort (mufrad) ist. Ist er Muḍāf wie hier oder einem Muḍāf ähnlich, ist er deklinierbar und manṣūb mit sichtbarer Fatḥa; ḫāsirun ist der Ḫabar."],
    ar: ["ما إعراب «طالبَ» في جملة: لا طالبَ علمٍ خاسرٌ؟", ["اسم لا معرب منصوب", "اسم لا مبني على الفتح", "مبتدأ مرفوع", "حال منصوبة"], "اسم لا النافية للجنس يُبنى إذا كان مفردًا، فإذا كان مضافًا كما هنا أو شبيهًا بالمضاف أُعرب ونُصب بالفتحة الظاهرة، و«خاسر» خبرها."] },

  { id: "nht-074", s: "nahw", g: 4, d: 4, t: ["kana-sisters"], src: "Ibn ʿAqīl, Sharḥ Alfiyyat Ibn Mālik, bāb kāna wa-akhawātuhā",
    en: ["In the often-cited grammar example إِذَا كَانَ الشِّتَاءُ فَأَدْفِئُونِي, how is kāna analysed?", ["Kāna tāmma; al-shitāʾ is its fāʿil", "Kāna nāqiṣa with an omitted khabar", "Kāna zāʾida with no effect at all", "Kāna nāqiṣa; al-shitāʾ is its khabar"], "Here kāna means \"to come, to occur\" and is complete in itself: it needs only a marfūʿ fāʿil and no khabar. Ibn Mālik says the tāmm kāna is content with its rafʿ."],
    de: ["Wie wird kāna im häufig zitierten Grammatikbeispiel إِذَا كَانَ الشِّتَاءُ فَأَدْفِئُونِي analysiert?", ["Kāna tāmma; aš-šitāʾ ist sein Fāʿil", "Kāna nāqiṣa mit ausgelassenem Ḫabar", "Kāna zāʾida ganz ohne Wirkung", "Kāna nāqiṣa; aš-šitāʾ ist sein Ḫabar"], "Kāna bedeutet hier „kommen, eintreten“ und ist in sich vollständig: Es braucht nur einen Fāʿil im rafʿ und keinen Ḫabar. Ibn Mālik sagt, das vollständige kāna begnüge sich mit seinem rafʿ."],
    ar: ["كيف تُعرب «كان» في الشاهد النحوي المشهور: إذا كانَ الشتاءُ فأدفئوني؟", ["تامة، و«الشتاء» فاعلها", "ناقصة وخبرها محذوف", "زائدة لا عمل لها", "ناقصة، و«الشتاء» خبرها"], "«كان» هنا بمعنى «جاء» أو «حدث» فهي تامة تكتفي بمرفوعها فاعلًا ولا تحتاج إلى خبر، وقد قال ابن مالك إن ذا التمام ما برفع يكتفي."] },

  { id: "nht-075", s: "nahw", g: 4, d: 5, t: ["kana-sisters", "grammar-schools"], src: "Ibn Hishām, Sharḥ Qaṭr al-Nadā, on mā, lā, lāta and in that work like laysa",
    en: ["Which statement correctly describes the two Arab usages in مَا خَالِدٌ مُسَافِر?", ["Ḥijāz makes mā work like laysa (musāfiran); Tamīm leave it marfūʿ", "Tamīm make mā work like laysa; Ḥijāz leave the khabar marfūʿ", "Both make the khabar manṣūb when it comes after the ism", "Both leave the khabar marfūʿ, since mā is a particle"], "In the dialect of the Ḥijāz, mā governs like laysa under conditions (e.g. the khabar not placed first, no illā), giving mā khālidun musāfiran. Banū Tamīm do not let it govern and say mā khālidun musāfirun."],
    de: ["Welche Aussage beschreibt die beiden arabischen Gebrauchsweisen in مَا خَالِدٌ مُسَافِر richtig?", ["Ḥiǧāz lässt mā wie laisa wirken (musāfiran); Tamīm lässt es marfūʿ", "Tamīm lässt mā wie laisa wirken; Ḥiǧāz lässt den Ḫabar marfūʿ", "Beide setzen den Ḫabar in den naṣb, wenn er nach dem Ism steht", "Beide lassen den Ḫabar marfūʿ, da mā eine Partikel ist"], "Im Dialekt des Ḥiǧāz wirkt mā unter Bedingungen (z. B. kein vorangestellter Ḫabar, kein illā) wie laisa: mā ḫālidun musāfiran. Die Banū Tamīm lassen es nicht wirken und sagen mā ḫālidun musāfirun."],
    ar: ["ما الوصف الصحيح للغتين في: ما خالدٌ مسافر؟", ["الحجازيون يُعملون «ما» عمل ليس فينصبون، وتميم يرفعون", "تميم يُعملونها عمل ليس، والحجازيون يرفعون", "الفريقان ينصبان الخبر إذا تأخر عن الاسم", "الفريقان يرفعان الخبر لأن «ما» حرف"], "أهل الحجاز يُعملون «ما» عمل ليس بشروط منها ألا يتقدم الخبر وألا يُنتقض النفي بإلا فيقولون: ما خالدٌ مسافرًا، وبنو تميم يهملونها فيقولون: ما خالدٌ مسافرٌ."] },

  { id: "nht-076", s: "nahw", g: 4, d: 5, t: ["nominal-sentence", "mushtaqqat"], src: "Ibn ʿAqīl, Sharḥ Alfiyyat Ibn Mālik, bāb al-ibtidāʾ",
    en: ["In the question أَقَادِمٌ أَخَوَاكَ؟, what is the iʿrāb of أَخَوَاكَ?", ["Fāʿil of qādim, standing in for the khabar", "Mubtadaʾ placed after its khabar qādim", "Badal of the participle qādim", "Khabar of the mubtadaʾ qādim"], "Qādim is an active participle relying on the interrogative, so it is mubtadaʾ and works like its verb; akhawāka is its fāʿil, which fills the place of the khabar. It cannot be a delayed mubtadaʾ, since a khabar for a dual would have to be dual (qādimāni)."],
    de: ["Wie lautet der Iʿrāb von أَخَوَاكَ in der Frage أَقَادِمٌ أَخَوَاكَ؟?", ["Fāʿil von qādim, an Stelle des Ḫabar", "Nachgestelltes Mubtadaʾ mit Ḫabar qādim", "Badal des Partizips qādim", "Ḫabar des Mubtadaʾ qādim"], "Qādim ist ein aktives Partizip, das sich auf die Frage stützt; es ist daher Mubtadaʾ und wirkt wie sein Verb, und aḫawāka ist sein Fāʿil, der den Platz des Ḫabar ausfüllt. Ein nachgestelltes Mubtadaʾ ist ausgeschlossen, da der Ḫabar eines Duals im Dual stehen müsste (qādimāni)."],
    ar: ["ما إعراب «أخواك» في: أقادمٌ أخواكَ؟", ["فاعل لـ«قادم» سدّ مسدّ الخبر", "مبتدأ مؤخر خبره «قادم»", "بدل من «قادم»", "خبر للمبتدأ «قادم»"], "«قادم» وصف اعتمد على الاستفهام فهو مبتدأ يعمل عمل فعله، و«أخواك» فاعله سدّ مسدّ الخبر، ولا يصح أن يكون مبتدأً مؤخرًا لعدم المطابقة، إذ لو كان كذلك لقيل: أقادمان أخواك."] },

  { id: "nht-077", s: "nahw", g: 4, d: 4, t: ["weak-verbs"], src: "al-Ḥamlāwī, Shadhā al-ʿArf fī Fann al-Ṣarf, on the lafīf verb",
    en: ["How is the verb وَقَى (to protect), root w-q-y, classified?", ["Lafīf mafrūq", "Lafīf maqrūn", "Ajwaf", "Muḍaʿʿaf"], "Its first and last radicals are weak, separated by a sound letter, which is lafīf mafrūq. Lafīf maqrūn has two adjacent weak radicals, as in ṭawā (ṭ-w-y)."],
    de: ["Wie wird das Verb وَقَى (schützen), Wurzel w-q-y, eingeordnet?", ["Lafīf mafrūq", "Lafīf maqrūn", "Aǧwaf", "Muḍaʿʿaf"], "Sein erster und letzter Radikal sind schwach und durch einen gesunden Buchstaben getrennt: lafīf mafrūq. Lafīf maqrūn hat zwei benachbarte schwache Radikale, wie ṭawā (ṭ-w-y)."],
    ar: ["ما نوع الفعل «وقى» من (و ق ي)؟", ["لفيف مفروق", "لفيف مقرون", "أجوف", "مضعّف"], "اعتلت فاؤه ولامه وفصل بينهما حرف صحيح فهو لفيف مفروق، وأما اللفيف المقرون فاجتمع فيه حرفا علة متجاوران نحو «طوى»."] },

  { id: "nht-078", s: "nahw", g: 4, d: 5, t: ["verb-forms", "weak-verbs"], src: "al-Ḥamlāwī, Shadhā al-ʿArf fī Fann al-Ṣarf, on ibdāl in iftaʿala",
    en: ["What is the form VIII (iftaʿala) verb from the root ṣ-b-r?", ["اِصْطَبَرَ", "اِصْتَبَرَ", "اِتْصَبَرَ", "اِصْدَبَرَ"], "When the first radical of iftaʿala is ṣād, ḍād, ṭāʾ or ẓāʾ, the infixed tāʾ becomes ṭāʾ for ease of pronunciation: iṣṭabara. After dāl, dhāl or zāy it becomes dāl, as in izdaḥama."],
    de: ["Wie lautet der VIII. Stamm (iftaʿala) der Wurzel ṣ-b-r?", ["اِصْطَبَرَ", "اِصْتَبَرَ", "اِتْصَبَرَ", "اِصْدَبَرَ"], "Ist der erste Radikal von iftaʿala Ṣād, Ḍād, Ṭāʾ oder Ẓāʾ, wird das eingefügte Tāʾ zur leichteren Aussprache zu Ṭāʾ: iṣṭabara. Nach Dāl, Ḏāl oder Zāy wird es zu Dāl, wie in izdaḥama."],
    ar: ["ما صيغة «افتعل» من مادة (ص ب ر)؟", ["اصطبر", "اصتبر", "اتصبر", "اصدبر"], "إذا كانت فاء «افتعل» صادًا أو ضادًا أو طاءً أو ظاءً قُلبت تاؤه طاءً تخفيفًا فيقال: اصطبر، وإذا كانت دالًا أو ذالًا أو زايًا قُلبت دالًا نحو: ازدحم."] },

  { id: "nht-079", s: "nahw", g: 4, d: 4, t: ["verbal-sentence", "fail"], src: "Ibn ʿAqīl, Sharḥ Alfiyyat Ibn Mālik, bāb al-fāʿil",
    en: ["Which sentence follows the usage of most Arabs when a dual fāʿil comes after its verb?", ["حَضَرَ الطَّالِبَانِ", "حَضَرَا الطَّالِبَانِ", "حَضَرَتَا الطَّالِبَانِ", "حَضَرُوا الطَّالِبَانِ"], "When an explicit dual or plural fāʿil follows the verb, the verb stays singular. Adding a dual marker (ḥaḍarā al-ṭālibāni) is a known dialect of some tribes, nicknamed lughat akalūnī al-barāghīth, not the general usage."],
    de: ["Welcher Satz folgt dem Gebrauch der meisten Araber, wenn ein Fāʿil im Dual nach seinem Verb steht?", ["حَضَرَ الطَّالِبَانِ", "حَضَرَا الطَّالِبَانِ", "حَضَرَتَا الطَّالِبَانِ", "حَضَرُوا الطَّالِبَانِ"], "Folgt ein ausdrücklicher Fāʿil im Dual oder Plural dem Verb, bleibt das Verb im Singular. Ein Dualzeichen am Verb (ḥaḍarā aṭ-ṭālibāni) ist ein bekannter Dialekt einiger Stämme, genannt luġat akalūnī l-barāġīṯ, nicht der allgemeine Gebrauch."],
    ar: ["أيّ الجمل على لغة أكثر العرب إذا تأخر الفاعل المثنى عن فعله؟", ["حضرَ الطالبانِ", "حضرا الطالبانِ", "حضرتا الطالبانِ", "حضروا الطالبانِ"], "إذا أُسند الفعل إلى فاعل ظاهر مثنى أو مجموع جُرِّد من علامة التثنية والجمع، وإلحاقها به لغة لبعض العرب تُعرف بلغة «أكلوني البراغيث» وليست اللغة الغالبة."] },

  { id: "nht-080", s: "nahw", g: 4, d: 5, t: ["conditional", "jazm"], src: "Ibn Hishām, Sharḥ Qaṭr al-Nadā, on the conditional nouns",
    en: ["In the sentence مَنْ يَجْتَهِدْ يَنْجَحْ, what is the iʿrāb of مَنْ?", ["Conditional noun, mabnī, in the position of rafʿ as mubtadaʾ", "Relative noun, mabnī, in the position of rafʿ as fāʿil", "Conditional particle with no position in iʿrāb", "Interrogative noun, mabnī, in the position of naṣb"], "Man is a conditional noun that puts both verbs in jazm, so it is not a relative (which would leave them marfūʿ) nor a particle. As a noun it needs a position, and since the verb yajtahid is intransitive, man is in the position of a mubtadaʾ."],
    de: ["Wie lautet der Iʿrāb von مَنْ im Satz مَنْ يَجْتَهِدْ يَنْجَحْ?", ["Bedingungsnomen, mabnī, an Stelle des rafʿ als Mubtadaʾ", "Relativnomen, mabnī, an Stelle des rafʿ als Fāʿil", "Bedingungspartikel ohne Stelle im Iʿrāb", "Fragenomen, mabnī, an Stelle des naṣb"], "Man ist ein Bedingungsnomen, das beide Verben in den ǧazm setzt; es ist daher weder Relativum (dann blieben sie marfūʿ) noch Partikel. Als Nomen braucht es eine Satzstelle, und da yaǧtahid intransitiv ist, steht man an Stelle eines Mubtadaʾ."],
    ar: ["ما إعراب «مَن» في جملة: مَن يجتهدْ ينجحْ؟", ["اسم شرط مبني في محل رفع مبتدأ", "اسم موصول مبني في محل رفع فاعل", "حرف شرط لا محل له من الإعراب", "اسم استفهام مبني في محل نصب"], "«مَن» اسم شرط جازم جزم الفعلين، فليست موصولة إذ لو كانت كذلك لرُفع الفعلان، وليست حرفًا، ولما كان الفعل «يجتهد» لازمًا كانت في محل رفع مبتدأ."] },
];
